(function(){"use strict";if(document.readyState!=="loading"){throw new Error("Blogger embed must load synchronously during HTML parsing");}document.write("<div id=\"ocdExhibitionPage\">\n\n<style>\n/* =========================================================\n   OCD - PH\u00d2NG TRI\u1ec2N L\u00c3M\n   EXHIBITION GALLERY v1.4.0\n\n   C\u01a0 CH\u1ebe TRI\u1ec2N L\u00c3M:\n   ---------------------------------------------------------\n   - B\u00e0i \u0111\u01b0\u1ee3c ch\u1ecdn khi Nh\u1eadn x\u00e9t GVCN ch\u1ee9a t\u1eeb \"Ngon\"\n   - \"Ngon\" ch\u1ec9 d\u00f9ng l\u00e0m \u0111i\u1ec1u ki\u1ec7n n\u1ed9i b\u1ed9\n   - KH\u00d4NG hi\u1ec3n th\u1ecb \u0110i\u1ec3m GVCN\n   - KH\u00d4NG hi\u1ec3n th\u1ecb Nh\u1eadn x\u00e9t GVCN\n   - KH\u00d4NG s\u1eafp x\u1ebfp theo \u0111i\u1ec3m\n\n   GI\u1eee:\n   - X\u00f3aBai\n   - Lo\u1ea1i b\u1ed3i bi\u1ec3u / thu ho\u1ea1ch / l\u00fd thuy\u1ebft\n   - T\u00ecm ki\u1ebfm\n   - L\u1ecdc kh\u00f3a / t\u1ed5\n   - M\u1edbi nh\u1ea5t / c\u0169 nh\u1ea5t\n   - Ph\u00e2n trang\n   - Lightbox\n   - Avatar\n   - Khung avatar\n   - Linh th\u00fa canonical t\u1eeb Reward Core\n   - Mobile 2 c\u1ed9t\n   - Tablet 3 c\u1ed9t\n   - Desktop 4 c\u1ed9t\n========================================================= */\n\n\n/* =========================================================\n   ROOT\n========================================================= */\n\n#ocdExhibitionPage{\n    --ex-paper:#fffdf8;\n    --ex-white:#ffffff;\n    --ex-ink:#2f2924;\n    --ex-muted:#786f66;\n    --ex-brown:#704b35;\n    --ex-brown-dark:#4d3225;\n    --ex-gold:#b88636;\n    --ex-gold-dark:#8a6428;\n    --ex-gold-soft:#f5e7c6;\n    --ex-line:#eadfce;\n\n    max-width:1440px;\n    margin:0 auto;\n    padding:0 14px 60px;\n\n    font-family:Arial,Helvetica,sans-serif;\n    color:var(--ex-ink);\n}\n\n#ocdExhibitionPage *,\n#ocdExhibitionPage *::before,\n#ocdExhibitionPage *::after{\n    box-sizing:border-box;\n}\n\n#ocdExhibitionPage button,\n#ocdExhibitionPage input,\n#ocdExhibitionPage select{\n    font:inherit;\n}\n\n\n/* =========================================================\n   HERO\n========================================================= */\n\n.ex-hero{\n    position:relative;\n    overflow:hidden;\n    max-width:1280px;\n    margin:24px auto 22px;\n    padding:55px 28px 50px;\n\n    border:1px solid #ddc58e;\n    border-radius:26px;\n\n    background:\n        radial-gradient(\n            circle at 10% 10%,\n            rgba(184,134,54,.18),\n            transparent 31%\n        ),\n        radial-gradient(\n            circle at 92% 85%,\n            rgba(112,75,53,.12),\n            transparent 34%\n        ),\n        linear-gradient(\n            135deg,\n            #fff8e9,\n            #fffdf8 48%,\n            #faf1df\n        );\n\n    box-shadow:\n        0 16px 45px rgba(68,45,30,.10);\n\n    text-align:center;\n}\n\n.ex-hero::before,\n.ex-hero::after{\n    content:\"\";\n    position:absolute;\n    border:1px solid rgba(184,134,54,.22);\n    border-radius:50%;\n    pointer-events:none;\n}\n\n.ex-hero::before{\n    width:210px;\n    height:210px;\n    left:-115px;\n    top:-110px;\n}\n\n.ex-hero::after{\n    width:260px;\n    height:260px;\n    right:-145px;\n    bottom:-165px;\n}\n\n.ex-hero-kicker{\n    position:relative;\n    z-index:1;\n\n    margin-bottom:10px;\n\n    color:var(--ex-gold-dark);\n\n    font-size:12px;\n    font-weight:900;\n    letter-spacing:2.5px;\n}\n\n.ex-hero-title{\n    position:relative;\n    z-index:1;\n\n    margin:0;\n\n    color:var(--ex-brown-dark);\n\n    font-family:\n        Georgia,\n        \"Times New Roman\",\n        serif;\n\n    font-size:46px;\n    line-height:1.15;\n    font-weight:700;\n}\n\n.ex-hero-line{\n    position:relative;\n    z-index:1;\n\n    width:76px;\n    height:2px;\n\n    margin:18px auto;\n\n    background:\n        linear-gradient(\n            90deg,\n            transparent,\n            var(--ex-gold),\n            transparent\n        );\n}\n\n.ex-hero-desc{\n    position:relative;\n    z-index:1;\n\n    max-width:720px;\n    margin:0 auto;\n\n    color:#665b52;\n\n    font-size:14px;\n    line-height:1.8;\n}\n\n\n/* =========================================================\n   STATS\n========================================================= */\n\n.ex-stats{\n    max-width:1000px;\n    margin:-4px auto 24px;\n\n    display:grid;\n\n    grid-template-columns:\n        repeat(4,minmax(0,1fr));\n\n    gap:10px;\n}\n\n.ex-stat{\n    min-width:0;\n\n    padding:17px 10px;\n\n    border:1px solid var(--ex-line);\n    border-radius:15px;\n\n    background:#fff;\n\n    text-align:center;\n\n    box-shadow:\n        0 5px 18px rgba(45,35,27,.05);\n}\n\n.ex-stat-value{\n    color:var(--ex-brown-dark);\n\n    font-size:25px;\n    line-height:1.1;\n    font-weight:900;\n}\n\n.ex-stat-label{\n    margin-top:6px;\n\n    color:var(--ex-muted);\n\n    font-size:10px;\n    line-height:1.35;\n    font-weight:800;\n\n    text-transform:uppercase;\n}\n\n\n/* =========================================================\n   CONTROLS\n========================================================= */\n\n.ex-controls{\n    max-width:1280px;\n\n    margin:0 auto 22px;\n\n    padding:15px;\n\n    border:1px solid var(--ex-line);\n    border-radius:18px;\n\n    background:#fff;\n\n    box-shadow:\n        0 6px 22px rgba(45,35,27,.06);\n}\n\n.ex-search-row{\n    display:grid;\n\n    grid-template-columns:\n        minmax(220px,1.7fr)\n        minmax(120px,.7fr)\n        minmax(120px,.7fr)\n        minmax(150px,.8fr);\n\n    gap:9px;\n}\n\n.ex-search-wrap{\n    position:relative;\n}\n\n.ex-search-icon{\n    position:absolute;\n\n    left:13px;\n    top:50%;\n\n    transform:translateY(-50%);\n\n    color:#9a8c7e;\n\n    font-size:15px;\n\n    pointer-events:none;\n}\n\n.ex-input,\n.ex-select{\n    width:100%;\n    height:45px;\n\n    border:1px solid #ddd4ca;\n    border-radius:11px;\n\n    background:#fff;\n    color:var(--ex-ink);\n\n    outline:none;\n\n    font-size:13px;\n}\n\n.ex-input{\n    padding:0 13px 0 38px;\n}\n\n.ex-select{\n    padding:0 11px;\n    cursor:pointer;\n}\n\n.ex-input:focus,\n.ex-select:focus{\n    border-color:var(--ex-gold);\n\n    box-shadow:\n        0 0 0 3px rgba(184,134,54,.11);\n}\n\n\n/* =========================================================\n   RESULT BAR\n========================================================= */\n\n.ex-result-bar{\n    max-width:1280px;\n\n    margin:0 auto 14px;\n\n    display:flex;\n\n    align-items:center;\n    justify-content:space-between;\n\n    gap:12px;\n}\n\n.ex-result-text{\n    color:var(--ex-muted);\n\n    font-size:12px;\n    line-height:1.5;\n}\n\n.ex-result-text strong{\n    color:var(--ex-brown-dark);\n}\n\n.ex-reset{\n    flex:0 0 auto;\n\n    padding:8px 12px;\n\n    border:1px solid var(--ex-line);\n    border-radius:9px;\n\n    background:#fff;\n    color:var(--ex-brown);\n\n    cursor:pointer;\n\n    font-size:10px;\n    font-weight:900;\n}\n\n.ex-reset:hover{\n    border-color:var(--ex-gold);\n}\n\n\n/* =========================================================\n   STATES\n========================================================= */\n\n.ex-state{\n    display:none;\n\n    max-width:900px;\n\n    margin:25px auto;\n\n    padding:24px;\n\n    border-radius:16px;\n\n    text-align:center;\n\n    font-size:13px;\n    line-height:1.7;\n}\n\n.ex-state.visible{\n    display:block;\n}\n\n.ex-loading{\n    background:#f8f6f2;\n    color:#766b62;\n}\n\n.ex-error{\n    background:#fef2f2;\n    color:#991b1b;\n}\n\n.ex-empty{\n    background:#faf8f5;\n    color:#786f66;\n}\n\n\n/* =========================================================\n   GALLERY\n========================================================= */\n\n.ex-grid{\n    max-width:1280px;\n\n    margin:0 auto;\n\n    display:grid;\n\n    grid-template-columns:\n        repeat(4,minmax(0,1fr));\n\n    gap:17px;\n}\n\n\n/* =========================================================\n   CARD\n========================================================= */\n\n.ex-card{\n    min-width:0;\n\n    overflow:hidden;\n\n    display:flex;\n    flex-direction:column;\n\n    border:1px solid #e7ded3;\n    border-radius:17px;\n\n    background:#fff;\n\n    box-shadow:\n        0 7px 24px rgba(54,41,31,.07);\n\n    transition:\n        transform .2s ease,\n        box-shadow .2s ease,\n        border-color .2s ease;\n}\n\n.ex-card:hover{\n    transform:translateY(-3px);\n\n    border-color:#d8bd82;\n\n    box-shadow:\n        0 13px 32px rgba(54,41,31,.12);\n}\n\n\n/* =========================================================\n   WORK IMAGE\n========================================================= */\n\n.ex-image-box{\n    position:relative;\n\n    width:100%;\n\n    aspect-ratio:4/5;\n\n    overflow:hidden;\n\n    background:\n        linear-gradient(\n            135deg,\n            #f3eee8,\n            #ebe4db\n        );\n\n    cursor:pointer;\n}\n\n.ex-image{\n    display:block;\n\n    width:100%;\n    height:100%;\n\n    object-fit:cover;\n\n    transition:\n        transform .35s ease;\n}\n\n.ex-card:hover .ex-image{\n    transform:scale(1.025);\n}\n\n.ex-no-image{\n    width:100%;\n    height:100%;\n\n    display:flex;\n\n    flex-direction:column;\n\n    align-items:center;\n    justify-content:center;\n\n    gap:8px;\n\n    color:#9a8d82;\n}\n\n.ex-no-image-icon{\n    font-size:34px;\n}\n\n.ex-no-image-text{\n    font-size:10px;\n}\n\n\n/* =========================================================\n   CARD BODY\n========================================================= */\n\n.ex-card-body{\n    flex:1;\n\n    display:flex;\n    flex-direction:column;\n\n    padding:14px 14px 13px;\n}\n\n\n/* =========================================================\n   STUDENT HEADER\n========================================================= */\n\n.ex-student-header{\n    min-width:0;\n\n    display:flex;\n\n    align-items:center;\n\n    gap:10px;\n}\n\n\n/* =========================================================\n   AVATAR\n========================================================= */\n\n.ex-avatar{\n    position:relative;\n\n    flex:0 0 48px;\n\n    width:48px;\n    height:48px;\n\n    display:flex;\n\n    align-items:center;\n    justify-content:center;\n}\n\n.ex-avatar-core{\n    position:absolute;\n\n    left:5px;\n    top:5px;\n\n    width:38px;\n    height:38px;\n\n    overflow:hidden;\n\n    display:flex;\n\n    align-items:center;\n    justify-content:center;\n\n    border-radius:50%;\n\n    border:1px solid #e2d7ca;\n\n    background:\n        radial-gradient(\n            circle at 35% 25%,\n            #fff,\n            #f2e9dc 68%,\n            #e1d1bc\n        );\n}\n\n.ex-avatar-core img{\n    display:block;\n\n    width:100%;\n    height:100%;\n\n    object-fit:cover;\n}\n\n.ex-avatar-fallback{\n    color:#8a6b50;\n\n    font-size:17px;\n    font-weight:900;\n    line-height:1;\n}\n\n.ex-avatar-frame{\n    position:absolute;\n\n    z-index:2;\n\n    inset:0;\n\n    width:48px;\n    height:48px;\n\n    object-fit:contain;\n\n    pointer-events:none;\n}\n\n\n/* =========================================================\n   STUDENT INFO\n========================================================= */\n\n.ex-student-info{\n    min-width:0;\n    flex:1;\n}\n\n.ex-author{\n    color:var(--ex-brown-dark);\n\n    font-size:16px;\n    line-height:1.3;\n    font-weight:900;\n\n    overflow-wrap:anywhere;\n}\n\n.ex-assignment{\n    margin-top:3px;\n\n    color:var(--ex-gold-dark);\n\n    font-size:10px;\n    line-height:1.45;\n    font-weight:800;\n}\n\n\n/* =========================================================\n   META\n========================================================= */\n\n.ex-meta{\n    display:flex;\n\n    flex-wrap:wrap;\n\n    gap:5px;\n\n    margin-top:9px;\n}\n\n.ex-chip{\n    padding:5px 7px;\n\n    border:1px solid #ece3d8;\n    border-radius:999px;\n\n    background:#faf8f5;\n\n    color:#75685d;\n\n    font-size:9px;\n    line-height:1;\n    font-weight:800;\n}\n\n\n/* =========================================================\n   FOOTER\n========================================================= */\n\n.ex-card-footer{\n    margin-top:auto;\n\n    padding-top:13px;\n\n    display:flex;\n\n    align-items:center;\n    justify-content:space-between;\n\n    gap:8px;\n}\n\n.ex-footer-left{\n    min-width:0;\n    flex:1;\n\n    display:flex;\n\n    align-items:center;\n    flex-wrap:wrap;\n\n    gap:7px;\n}\n\n.ex-time{\n    color:#94887d;\n\n    font-size:9px;\n    line-height:1.35;\n}\n\n\n/* =========================================================\n   SPIRIT BEASTS\n========================================================= */\n\n.ex-footer-beasts,\n.ex-lightbox-beasts{\n    min-width:0;\n\n    display:none;\n\n    align-items:center;\n    flex-wrap:wrap;\n\n    gap:4px;\n}\n\n.ex-footer-beasts.visible,\n.ex-lightbox-beasts.visible{\n    display:flex;\n}\n\n.ex-footer-beast{\n    position:relative;\n\n    width:30px;\n    height:30px;\n\n    flex:0 0 30px;\n\n    display:flex;\n\n    align-items:center;\n    justify-content:center;\n\n    border:\n        1px solid rgba(184,134,54,.28);\n\n    border-radius:50%;\n\n    background:\n        radial-gradient(\n            circle at 40% 30%,\n            #fff,\n            #f7eedb 65%,\n            #ead7ad\n        );\n\n    box-shadow:\n        0 3px 9px rgba(85,61,35,.12);\n\n    animation:\n        exBeastFloat\n        3s\n        ease-in-out\n        infinite;\n}\n\n.ex-footer-beast::after{\n    content:\"\";\n\n    position:absolute;\n\n    left:16%;\n    right:16%;\n    bottom:-3px;\n\n    height:4px;\n\n    border-radius:50%;\n\n    background:\n        rgba(80,57,35,.14);\n\n    filter:blur(2px);\n\n    animation:\n        exBeastShadow\n        3s\n        ease-in-out\n        infinite;\n}\n\n.ex-footer-beast-image{\n    position:relative;\n\n    z-index:1;\n\n    display:block;\n\n    width:27px;\n    height:27px;\n\n    object-fit:contain;\n\n    animation:\n        exBeastLife\n        4.5s\n        ease-in-out\n        infinite;\n\n    filter:\n        drop-shadow(\n            0 2px 3px rgba(72,47,25,.20)\n        );\n}\n\n@keyframes exBeastFloat{\n\n    0%,100%{\n        transform:translateY(0);\n    }\n\n    50%{\n        transform:translateY(-3px);\n    }\n}\n\n@keyframes exBeastLife{\n\n    0%,100%{\n        transform:\n            rotate(-2deg)\n            scale(1);\n    }\n\n    25%{\n        transform:\n            rotate(2deg)\n            scale(1.04);\n    }\n\n    50%{\n        transform:\n            rotate(-1deg)\n            scale(.98);\n    }\n\n    75%{\n        transform:\n            rotate(2deg)\n            scale(1.025);\n    }\n}\n\n@keyframes exBeastShadow{\n\n    0%,100%{\n        transform:scaleX(1);\n        opacity:.6;\n    }\n\n    50%{\n        transform:scaleX(.75);\n        opacity:.35;\n    }\n}\n\n@media(prefers-reduced-motion:reduce){\n\n    .ex-footer-beast,\n    .ex-footer-beast::after,\n    .ex-footer-beast-image{\n        animation:none!important;\n    }\n}\n\n\n/* =========================================================\n   VIEW BUTTON\n========================================================= */\n\n.ex-view{\n    flex:0 0 auto;\n\n    padding:6px 8px;\n\n    border:0;\n    border-radius:8px;\n\n    background:#f5efe6;\n\n    color:#6d4b35;\n\n    cursor:pointer;\n\n    font-size:9px;\n    font-weight:900;\n}\n\n.ex-view:hover{\n    background:#eee2cf;\n}\n\n\n/* =========================================================\n   PAGINATION\n========================================================= */\n\n.ex-pages{\n    display:none;\n\n    max-width:1280px;\n\n    margin:25px auto 0;\n\n    flex-wrap:wrap;\n\n    align-items:center;\n    justify-content:center;\n\n    gap:6px;\n}\n\n.ex-pages.visible{\n    display:flex;\n}\n\n.ex-page{\n    min-width:38px;\n    height:38px;\n\n    padding:0 10px;\n\n    border:1px solid #e0d7cc;\n    border-radius:9px;\n\n    background:#fff;\n\n    color:#66594f;\n\n    cursor:pointer;\n\n    font-size:11px;\n    font-weight:900;\n}\n\n.ex-page:hover{\n    border-color:var(--ex-gold);\n    color:var(--ex-brown);\n}\n\n.ex-page.active{\n    border-color:var(--ex-brown);\n\n    background:var(--ex-brown);\n\n    color:#fff;\n}\n\n.ex-page:disabled{\n    opacity:.35;\n    cursor:default;\n}\n\n.ex-page-dots{\n    padding:0 3px;\n\n    color:#94887d;\n\n    font-size:14px;\n    font-weight:900;\n}\n\n\n/* =========================================================\n   LIGHTBOX\n========================================================= */\n\n.ex-lightbox{\n    position:fixed;\n\n    z-index:999999;\n\n    inset:0;\n\n    display:none;\n\n    align-items:center;\n    justify-content:center;\n\n    padding:24px;\n\n    background:\n        rgba(20,16,13,.88);\n\n    backdrop-filter:\n        blur(7px);\n}\n\n.ex-lightbox.visible{\n    display:flex;\n}\n\n.ex-lightbox-dialog{\n    position:relative;\n\n    width:min(1040px,92vw);\n\n    max-height:90vh;\n\n    display:grid;\n\n    grid-template-columns:\n        minmax(0,1.5fr)\n        minmax(270px,.5fr);\n\n    overflow:hidden;\n\n    border-radius:18px;\n\n    background:#fff;\n\n    box-shadow:\n        0 30px 80px rgba(0,0,0,.4);\n}\n\n.ex-lightbox-image-wrap{\n    min-width:0;\n\n    display:flex;\n\n    align-items:center;\n    justify-content:center;\n\n    background:#171411;\n}\n\n.ex-lightbox-image{\n    display:block;\n\n    max-width:100%;\n    max-height:90vh;\n\n    object-fit:contain;\n}\n\n.ex-lightbox-info{\n    max-height:90vh;\n\n    overflow:auto;\n\n    padding:25px 22px;\n\n    background:#fffdf9;\n}\n\n.ex-lightbox-title{\n    margin:0;\n\n    color:var(--ex-brown-dark);\n\n    font-family:\n        Georgia,\n        \"Times New Roman\",\n        serif;\n\n    font-size:25px;\n    line-height:1.25;\n}\n\n.ex-lightbox-assignment{\n    margin-top:6px;\n\n    color:var(--ex-gold-dark);\n\n    font-size:12px;\n    font-weight:800;\n}\n\n\n/* =========================================================\n   LIGHTBOX META\n========================================================= */\n\n.ex-lightbox-meta-row{\n    margin-top:16px;\n\n    padding-top:13px;\n\n    border-top:\n        1px solid #eee3d4;\n}\n\n.ex-lightbox-meta{\n    color:#766a61;\n\n    font-size:11px;\n    line-height:1.7;\n}\n\n.ex-lightbox-date-beasts{\n    margin-top:7px;\n\n    display:flex;\n\n    align-items:center;\n    flex-wrap:wrap;\n\n    gap:7px;\n}\n\n.ex-lightbox-date{\n    color:#8b7e73;\n\n    font-size:10px;\n    line-height:1.45;\n}\n\n.ex-lightbox-beasts .ex-footer-beast{\n    width:31px;\n    height:31px;\n\n    flex-basis:31px;\n}\n\n.ex-lightbox-beasts .ex-footer-beast-image{\n    width:28px;\n    height:28px;\n}\n\n\n/* =========================================================\n   LIGHTBOX DESCRIPTION\n========================================================= */\n\n.ex-lightbox-curation{\n    margin-top:18px;\n\n    padding:13px;\n\n    border:\n        1px solid #ead9b9;\n\n    border-radius:11px;\n\n    background:#fff9ed;\n\n    color:#65594f;\n\n    font-size:11px;\n    line-height:1.7;\n}\n\n.ex-lightbox-curation-title{\n    display:block;\n\n    margin-bottom:4px;\n\n    color:#8a6428;\n\n    font-size:9px;\n    font-weight:900;\n\n    text-transform:uppercase;\n}\n\n.ex-original-link{\n    display:inline-flex;\n\n    align-items:center;\n    justify-content:center;\n\n    min-height:40px;\n\n    margin-top:18px;\n\n    padding:0 15px;\n\n    border-radius:9px;\n\n    background:var(--ex-brown);\n\n    color:#fff!important;\n\n    text-decoration:none!important;\n\n    font-size:11px;\n    font-weight:900;\n}\n\n.ex-close{\n    position:absolute;\n\n    z-index:5;\n\n    right:10px;\n    top:10px;\n\n    width:38px;\n    height:38px;\n\n    display:flex;\n\n    align-items:center;\n    justify-content:center;\n\n    border:\n        1px solid rgba(255,255,255,.35);\n\n    border-radius:50%;\n\n    background:\n        rgba(0,0,0,.62);\n\n    color:#fff;\n\n    cursor:pointer;\n\n    font-size:22px;\n    line-height:1;\n}\n\n\n/* =========================================================\n   NOTE\n========================================================= */\n\n.ex-note{\n    max-width:850px;\n\n    margin:32px auto 0;\n\n    color:#93867a;\n\n    text-align:center;\n\n    font-size:11px;\n    line-height:1.7;\n    font-weight:700;\n}\n\n\n/* =========================================================\n   TABLET\n========================================================= */\n\n@media(max-width:1050px){\n\n    .ex-grid{\n        grid-template-columns:\n            repeat(3,minmax(0,1fr));\n    }\n\n    .ex-search-row{\n        grid-template-columns:\n            minmax(220px,1.4fr)\n            repeat(3,minmax(120px,.7fr));\n    }\n}\n\n\n/* =========================================================\n   MOBILE\n========================================================= */\n\n@media(max-width:700px){\n\n    #ocdExhibitionPage{\n        padding-left:8px;\n        padding-right:8px;\n    }\n\n    .ex-hero{\n        margin-top:12px;\n\n        padding:\n            37px 16px 34px;\n\n        border-radius:20px;\n    }\n\n    .ex-hero-kicker{\n        font-size:9px;\n        letter-spacing:1.8px;\n    }\n\n    .ex-hero-title{\n        font-size:31px;\n    }\n\n    .ex-hero-desc{\n        font-size:12px;\n        line-height:1.65;\n    }\n\n    .ex-stats{\n        grid-template-columns:\n            repeat(4,minmax(0,1fr));\n\n        gap:5px;\n    }\n\n    .ex-stat{\n        padding:12px 3px;\n        border-radius:10px;\n    }\n\n    .ex-stat-value{\n        font-size:19px;\n    }\n\n    .ex-stat-label{\n        font-size:7px;\n    }\n\n    .ex-controls{\n        padding:10px;\n    }\n\n    .ex-search-row{\n        grid-template-columns:\n            repeat(2,minmax(0,1fr));\n    }\n\n    .ex-search-wrap{\n        grid-column:1/-1;\n    }\n\n    .ex-search-row .ex-select:last-child{\n        grid-column:1/-1;\n    }\n\n    .ex-input,\n    .ex-select{\n        height:42px;\n        font-size:11px;\n    }\n\n    .ex-result-bar{\n        align-items:flex-start;\n    }\n\n    .ex-result-text{\n        font-size:10px;\n    }\n\n    .ex-grid{\n        grid-template-columns:\n            repeat(2,minmax(0,1fr));\n\n        gap:8px;\n    }\n\n    .ex-card{\n        border-radius:12px;\n    }\n\n    .ex-card-body{\n        padding:9px 8px 8px;\n    }\n\n    .ex-student-header{\n        gap:6px;\n    }\n\n    .ex-avatar{\n        flex-basis:38px;\n\n        width:38px;\n        height:38px;\n    }\n\n    .ex-avatar-core{\n        left:4px;\n        top:4px;\n\n        width:30px;\n        height:30px;\n    }\n\n    .ex-avatar-frame{\n        width:38px;\n        height:38px;\n    }\n\n    .ex-avatar-fallback{\n        font-size:13px;\n    }\n\n    .ex-author{\n        font-size:12px;\n    }\n\n    .ex-assignment{\n        font-size:8px;\n    }\n\n    .ex-meta{\n        gap:3px;\n        margin-top:6px;\n    }\n\n    .ex-chip{\n        padding:4px 5px;\n        font-size:7px;\n    }\n\n    .ex-card-footer{\n        padding-top:9px;\n        gap:5px;\n    }\n\n    .ex-footer-left{\n        gap:4px;\n    }\n\n    .ex-time{\n        font-size:7px;\n    }\n\n    .ex-footer-beasts{\n        gap:2px;\n    }\n\n    .ex-footer-beast{\n        width:24px;\n        height:24px;\n\n        flex-basis:24px;\n    }\n\n    .ex-footer-beast-image{\n        width:21px;\n        height:21px;\n    }\n\n    .ex-view{\n        padding:5px;\n        font-size:7px;\n    }\n\n    .ex-page{\n        min-width:34px;\n        height:34px;\n\n        padding:0 8px;\n\n        font-size:10px;\n    }\n\n\n    /* LIGHTBOX MOBILE */\n\n    .ex-lightbox{\n        padding:18px 14px;\n    }\n\n    .ex-lightbox-dialog{\n        width:min(88vw,420px);\n\n        max-height:88vh;\n\n        display:block;\n\n        overflow:auto;\n\n        border-radius:15px;\n    }\n\n    .ex-lightbox-image-wrap{\n        width:100%;\n\n        min-height:0;\n\n        height:auto;\n\n        max-height:52vh;\n\n        padding:10px;\n\n        background:#171411;\n    }\n\n    .ex-lightbox-image{\n        width:auto;\n        height:auto;\n\n        max-width:100%;\n        max-height:48vh;\n\n        object-fit:contain;\n\n        margin:auto;\n    }\n\n    .ex-lightbox-info{\n        max-height:none;\n\n        padding:14px 13px 18px;\n    }\n\n    .ex-lightbox-title{\n        padding-right:25px;\n\n        font-size:18px;\n        line-height:1.3;\n    }\n\n    .ex-lightbox-assignment{\n        margin-top:4px;\n\n        font-size:10px;\n        line-height:1.45;\n    }\n\n    .ex-lightbox-meta-row{\n        margin-top:11px;\n        padding-top:9px;\n    }\n\n    .ex-lightbox-meta{\n        font-size:9px;\n        line-height:1.55;\n    }\n\n    .ex-lightbox-date-beasts{\n        margin-top:5px;\n        gap:5px;\n    }\n\n    .ex-lightbox-date{\n        font-size:8px;\n    }\n\n    .ex-lightbox-beasts{\n        gap:3px;\n    }\n\n    .ex-lightbox-beasts .ex-footer-beast{\n        width:25px;\n        height:25px;\n\n        flex-basis:25px;\n    }\n\n    .ex-lightbox-beasts .ex-footer-beast-image{\n        width:22px;\n        height:22px;\n    }\n\n    .ex-lightbox-curation{\n        margin-top:12px;\n\n        padding:10px;\n\n        font-size:9px;\n        line-height:1.6;\n    }\n\n    .ex-lightbox-curation-title{\n        font-size:8px;\n    }\n\n    .ex-original-link{\n        min-height:36px;\n\n        margin-top:12px;\n\n        padding:0 12px;\n\n        font-size:9px;\n    }\n\n    .ex-close{\n        right:7px;\n        top:7px;\n\n        width:32px;\n        height:32px;\n\n        font-size:19px;\n    }\n}\n\n\n@media(max-width:380px){\n\n    .ex-grid{\n        gap:6px;\n    }\n\n    .ex-card-body{\n        padding:8px 6px;\n    }\n\n    .ex-author{\n        font-size:11px;\n    }\n\n    .ex-lightbox{\n        padding:16px 12px;\n    }\n\n    .ex-lightbox-dialog{\n        width:90vw;\n    }\n\n    .ex-lightbox-image-wrap{\n        max-height:48vh;\n        padding:8px;\n    }\n\n    .ex-lightbox-image{\n        max-height:44vh;\n    }\n}\n\n</style>\n\n\n<!-- =========================================================\n     HERO\n========================================================= -->\n\n<section class=\"ex-hero\">\n\n    <div class=\"ex-hero-kicker\">\n        THANH PHONG TH\u01af M\u00d4N\n    </div>\n\n    <h1 class=\"ex-hero-title\">\n        Ph\u00f2ng tri\u1ec3n l\u00e3m OCD\n    </h1>\n\n    <div class=\"ex-hero-line\"></div>\n\n    <p class=\"ex-hero-desc\">\n        Kh\u00f4ng gian tr\u01b0ng b\u00e0y nh\u1eefng t\u00e1c ph\u1ea9m n\u1ed5i b\u1eadt\n        \u0111\u01b0\u1ee3c GVCN l\u1ef1a ch\u1ecdn trong qu\u00e1 tr\u00ecnh h\u1ecdc t\u1eadp v\u00e0 r\u00e8n luy\u1ec7n.\n    </p>\n\n</section>\n\n\n<!-- =========================================================\n     STATS\n========================================================= -->\n\n<section class=\"ex-stats\">\n\n    <div class=\"ex-stat\">\n        <div\n            id=\"exStatWorks\"\n            class=\"ex-stat-value\"\n        >-</div>\n\n        <div class=\"ex-stat-label\">\n            T\u00e1c ph\u1ea9m\n        </div>\n    </div>\n\n\n    <div class=\"ex-stat\">\n        <div\n            id=\"exStatStudents\"\n            class=\"ex-stat-value\"\n        >-</div>\n\n        <div class=\"ex-stat-label\">\n            H\u1ecdc vi\u00ean\n        </div>\n    </div>\n\n\n    <div class=\"ex-stat\">\n        <div\n            id=\"exStatGroups\"\n            class=\"ex-stat-value\"\n        >-</div>\n\n        <div class=\"ex-stat-label\">\n            T\u1ed5\n        </div>\n    </div>\n\n\n    <div class=\"ex-stat\">\n        <div\n            id=\"exStatCourses\"\n            class=\"ex-stat-value\"\n        >-</div>\n\n        <div class=\"ex-stat-label\">\n            Kh\u00f3a\n        </div>\n    </div>\n\n</section>\n\n\n<!-- =========================================================\n     CONTROLS\n========================================================= -->\n\n<section class=\"ex-controls\">\n\n    <div class=\"ex-search-row\">\n\n        <div class=\"ex-search-wrap\">\n\n            <span class=\"ex-search-icon\">\n                \u2315\n            </span>\n\n            <input\n                id=\"exSearch\"\n                class=\"ex-input\"\n                type=\"search\"\n                autocomplete=\"off\"\n                placeholder=\"T\u00ecm t\u00ean h\u1ecdc vi\u00ean ho\u1eb7c b\u00e0i t\u1eadp...\"\n            />\n\n        </div>\n\n\n        <select\n            id=\"exCourse\"\n            class=\"ex-select\"\n        >\n            <option value=\"\">\n                T\u1ea5t c\u1ea3 kh\u00f3a\n            </option>\n        </select>\n\n\n        <select\n            id=\"exGroup\"\n            class=\"ex-select\"\n        >\n            <option value=\"\">\n                T\u1ea5t c\u1ea3 t\u1ed5\n            </option>\n        </select>\n\n\n        <select\n            id=\"exSort\"\n            class=\"ex-select\"\n        >\n            <option value=\"newest\">\n                M\u1edbi nh\u1ea5t\n            </option>\n\n            <option value=\"oldest\">\n                C\u0169 nh\u1ea5t\n            </option>\n        </select>\n\n    </div>\n\n</section>\n\n\n<!-- =========================================================\n     RESULT\n========================================================= -->\n\n<div class=\"ex-result-bar\">\n\n    <div\n        id=\"exResultText\"\n        class=\"ex-result-text\"\n    >\n        \u0110ang chu\u1ea9n b\u1ecb tri\u1ec3n l\u00e3m...\n    </div>\n\n\n    <button\n        id=\"exReset\"\n        class=\"ex-reset\"\n        type=\"button\"\n    >\n        \u0110\u1eb7t l\u1ea1i b\u1ed9 l\u1ecdc\n    </button>\n\n</div>\n\n\n<!-- =========================================================\n     STATES\n========================================================= -->\n\n<div\n    id=\"exLoading\"\n    class=\"ex-state ex-loading visible\"\n>\n    \u0110ang t\u1ea3i c\u00e1c t\u00e1c ph\u1ea9m \u0111\u01b0\u1ee3c l\u1ef1a ch\u1ecdn...\n</div>\n\n\n<div\n    id=\"exError\"\n    class=\"ex-state ex-error\"\n></div>\n\n\n<div\n    id=\"exEmpty\"\n    class=\"ex-state ex-empty\"\n>\n    Kh\u00f4ng t\u00ecm th\u1ea5y t\u00e1c ph\u1ea9m ph\u00f9 h\u1ee3p.\n</div>\n\n\n<!-- =========================================================\n     GALLERY\n========================================================= -->\n\n<div\n    id=\"exGrid\"\n    class=\"ex-grid\"\n></div>\n\n\n<div\n    id=\"exPages\"\n    class=\"ex-pages\"\n></div>\n\n\n<div class=\"ex-note\">\n    Nh\u1eefng t\u00e1c ph\u1ea9m n\u1ed5i b\u1eadt \u0111\u01b0\u1ee3c l\u1ef1a ch\u1ecdn\n    v\u00e0 gi\u1edbi thi\u1ec7u t\u1ea1i Ph\u00f2ng tri\u1ec3n l\u00e3m OCD\n</div>\n\n\n<!-- =========================================================\n     LIGHTBOX\n========================================================= -->\n\n<div\n    id=\"exLightbox\"\n    class=\"ex-lightbox\"\n    aria-hidden=\"true\"\n>\n\n    <div\n        class=\"ex-lightbox-dialog\"\n        role=\"dialog\"\n        aria-modal=\"true\"\n        aria-label=\"Xem t\u00e1c ph\u1ea9m\"\n    >\n\n        <button\n            id=\"exClose\"\n            class=\"ex-close\"\n            type=\"button\"\n            aria-label=\"\u0110\u00f3ng\"\n        ></button>\n\n\n        <div class=\"ex-lightbox-image-wrap\">\n\n            <img\n                id=\"exLightboxImage\"\n                class=\"ex-lightbox-image\"\n                alt=\"T\u00e1c ph\u1ea9m\"\n            />\n\n        </div>\n\n\n        <div class=\"ex-lightbox-info\">\n\n            <h2\n                id=\"exLightboxName\"\n                class=\"ex-lightbox-title\"\n            ></h2>\n\n\n            <div\n                id=\"exLightboxAssignment\"\n                class=\"ex-lightbox-assignment\"\n            ></div>\n\n\n            <div class=\"ex-lightbox-meta-row\">\n\n                <div\n                    id=\"exLightboxMeta\"\n                    class=\"ex-lightbox-meta\"\n                ></div>\n\n\n                <div class=\"ex-lightbox-date-beasts\">\n\n                    <span\n                        id=\"exLightboxDate\"\n                        class=\"ex-lightbox-date\"\n                    ></span>\n\n\n                    <div\n                        id=\"exLightboxBeasts\"\n                        class=\"ex-lightbox-beasts\"\n                    ></div>\n\n                </div>\n\n            </div>\n\n\n            <div class=\"ex-lightbox-curation\">\n\n                <span class=\"ex-lightbox-curation-title\">\n                    Ph\u00f2ng tri\u1ec3n l\u00e3m OCD\n                </span>\n\n                T\u00e1c ph\u1ea9m \u0111\u01b0\u1ee3c l\u1ef1a ch\u1ecdn \u0111\u1ec3 gi\u1edbi thi\u1ec7u\n                trong kh\u00f4ng gian tri\u1ec3n l\u00e3m c\u1ee7a Thanh Phong Th\u01b0 M\u00f4n.\n\n            </div>\n\n\n            <a\n                id=\"exOriginalLink\"\n                class=\"ex-original-link\"\n                href=\"#\"\n                target=\"_blank\"\n                rel=\"noopener noreferrer\"\n            >\n                M\u1edf \u1ea3nh g\u1ed1c\n            </a>\n\n        </div>\n\n    </div>\n\n</div>\n\n\n<script>\n(function(){\n\n\"use strict\";\n\n\n/* =========================================================\n   SINGLE START\n========================================================= */\n\nif(window.OCDExhibitionV140Loaded){\n    return;\n}\n\nwindow.OCDExhibitionV140Loaded=true;\n\n\n/* =========================================================\n   CONFIG\n========================================================= */\n\nconst CONFIG={\n\n    version:\n        \"1.4.0\",\n\n    exhibitionKeyword:\n        \"ngon\",\n\n    mobilePageSize:\n        12,\n\n    desktopPageSize:\n        24,\n\n    maxBeastsPerCard:\n        8,\n\n    excludedNotes:[\n        \"boi bieu\",\n        \"thu hoach\",\n        \"ly thuyet\"\n    ],\n\n    works:\n        \"https://docs.google.com/spreadsheets/d/e/2PACX-1vRP5cc8duj1XrCXMrymo6Cj7aqIkWfX6bHxGeW-lXcSewfQXhM8fZ5rzbNIQ9mBeVuB8yYr_o1aBoYA/pub?gid=1023688821&single=true&output=csv\",\n\n    fallback:\n        \"https://docs.google.com/spreadsheets/d/1GJoTRsbq0kZfZrDdh0uCC667PwS3Bgkje2fHQnwnCKs/export?format=csv&gid=1837470623\",\n\n    deleteLog:\n        \"https://docs.google.com/spreadsheets/d/1GJoTRsbq0kZfZrDdh0uCC667PwS3Bgkje2fHQnwnCKs/export?format=csv&gid=521976322\"\n\n};\n\n\n/* =========================================================\n   SAFE CHARACTERS\n========================================================= */\n\nconst CHAR={\n\n    dot:\n        String.fromCodePoint(\n            0x00B7\n        ),\n\n    dash:\n        String.fromCodePoint(\n            0x2013\n        ),\n\n    previous:\n        String.fromCodePoint(\n            0x2039\n        ),\n\n    next:\n        String.fromCodePoint(\n            0x203A\n        ),\n\n    ellipsis:\n        String.fromCodePoint(\n            0x2026\n        ),\n\n    close:\n        String.fromCodePoint(\n            0x00D7\n        )\n\n};\n\n\n/* =========================================================\n   STATE\n========================================================= */\n\nconst state={\n\n    started:false,\n\n    loading:false,\n\n    RS:null,\n\n    workHeader:[],\n\n    allWorks:[],\n\n    workMap:new Map(),\n\n    exhibitionWorks:[],\n\n    filteredWorks:[],\n\n    deletedIds:new Set(),\n\n    giftMap:new Map(),\n\n    catalogReady:false,\n\n    catalogPromise:null,\n\n    accountMap:new Map(),\n\n    accountPromiseMap:new Map(),\n\n    page:1,\n\n    activeLightbox:null,\n\n    lightboxToken:0\n\n};\n\n\n/* =========================================================\n   BASIC\n========================================================= */\n\nfunction el(id){\n\n    return document\n        .getElementById(id);\n}\n\n\nfunction clean(v){\n\n    return String(\n        v===undefined\n        ||\n        v===null\n        ?\n        \"\"\n        :\n        v\n    ).trim();\n}\n\n\nfunction normalizeText(v){\n\n    return clean(v)\n\n        .toLowerCase()\n\n        .normalize(\"NFD\")\n\n        .replace(\n            /[\\u0300-\\u036f]/g,\n            \"\"\n        )\n\n        .replace(\n            /\u0111/g,\n            \"d\"\n        )\n\n        .replace(\n            /\\s+/g,\n            \" \"\n        );\n}\n\n\nfunction normalizeReward(v){\n\n    return normalizeText(v);\n}\n\n\nfunction normalizeCode(v){\n\n    const value=\n        clean(v);\n\n\n    if(\n        state.RS\n        &&\n        typeof state.RS.normalizeCode\n            ===\n            \"function\"\n    ){\n\n        try{\n\n            const result=\n                state.RS\n                    .normalizeCode(\n                        value\n                    );\n\n\n            if(result){\n                return result;\n            }\n\n        }catch(error){}\n    }\n\n\n    return value\n\n        .toUpperCase()\n\n        .replace(\n            /\\s+/g,\n            \"\"\n        );\n}\n\n\n/* =========================================================\n   CSV\n========================================================= */\n\nfunction parseCSV(text){\n\n    const rows=[];\n\n    let row=[];\n\n    let value=\"\";\n\n    let quote=false;\n\n\n    text=\n        String(text||\"\")\n\n        .replace(\n            /^\\uFEFF/,\n            \"\"\n        );\n\n\n    for(\n        let i=0;\n        i<text.length;\n        i++\n    ){\n\n        const c=\n            text[i];\n\n\n        if(c==='\"'){\n\n            if(\n                quote\n                &&\n                text[i+1]==='\"'\n            ){\n\n                value+='\"';\n\n                i++;\n\n            }else{\n\n                quote=\n                    !quote;\n            }\n\n            continue;\n        }\n\n\n        if(\n            c===\",\"\n            &&\n            !quote\n        ){\n\n            row.push(value);\n\n            value=\"\";\n\n            continue;\n        }\n\n\n        if(\n            (\n                c===\"\\n\"\n                ||\n                c===\"\\r\"\n            )\n            &&\n            !quote\n        ){\n\n            if(\n                c===\"\\r\"\n                &&\n                text[i+1]===\"\\n\"\n            ){\n                i++;\n            }\n\n\n            row.push(value);\n\n\n            if(\n                row.some(\n                    function(cell){\n\n                        return clean(cell);\n                    }\n                )\n            ){\n\n                rows.push(row);\n            }\n\n\n            row=[];\n\n            value=\"\";\n\n            continue;\n        }\n\n\n        value+=c;\n    }\n\n\n    if(\n        value\n        ||\n        row.length\n    ){\n\n        row.push(value);\n\n\n        if(\n            row.some(\n                function(cell){\n\n                    return clean(cell);\n                }\n            )\n        ){\n\n            rows.push(row);\n        }\n    }\n\n\n    return rows;\n}\n\n\n/* =========================================================\n   CSV OBJECTS\n========================================================= */\n\nfunction csvObjectsFromRows(rows){\n\n    if(\n        !Array.isArray(rows)\n        ||\n        rows.length<2\n    ){\n\n        return [];\n    }\n\n\n    const headers=\n        rows[0]\n        .map(\n            normalizeText\n        );\n\n\n    return rows\n\n        .slice(1)\n\n        .filter(\n            function(row){\n\n                return row.some(\n                    function(cell){\n\n                        return clean(cell);\n                    }\n                );\n            }\n        )\n\n        .map(\n            function(row){\n\n                const obj={};\n\n\n                headers.forEach(\n                    function(\n                        header,\n                        index\n                    ){\n\n                        if(header){\n\n                            obj[header]=\n                                row[index]\n                                ||\n                                \"\";\n                        }\n                    }\n                );\n\n\n                obj.__sourceRow=\n                    row.slice();\n\n\n                return obj;\n            }\n        );\n}\n\n\nfunction csvObjects(text){\n\n    return csvObjectsFromRows(\n        parseCSV(text)\n    );\n}\n\n\n/* =========================================================\n   CSV OUTPUT FOR CORE\n========================================================= */\n\nfunction csvCell(value){\n\n    const text=\n        String(\n            value===undefined\n            ||\n            value===null\n            ?\n            \"\"\n            :\n            value\n        );\n\n\n    if(\n        text.includes(\",\")\n        ||\n        text.includes('\"')\n        ||\n        text.includes(\"\\n\")\n        ||\n        text.includes(\"\\r\")\n    ){\n\n        return(\n            '\"'\n            +\n            text.replace(\n                /\"/g,\n                '\"\"'\n            )\n            +\n            '\"'\n        );\n    }\n\n\n    return text;\n}\n\n\nfunction rowsToCsv(rows){\n\n    return (rows||[])\n\n        .map(\n            function(row){\n\n                return (row||[])\n\n                    .map(csvCell)\n\n                    .join(\",\");\n            }\n        )\n\n        .join(\"\\n\");\n}\n\n\n/* =========================================================\n   COLUMN\n========================================================= */\n\nfunction column(\n    obj,\n    aliases\n){\n\n    if(!obj){\n        return \"\";\n    }\n\n\n    for(\n        const alias\n        of\n        aliases\n    ){\n\n        const key=\n            normalizeText(\n                alias\n            );\n\n\n        if(\n            Object.prototype\n                .hasOwnProperty\n                .call(\n                    obj,\n                    key\n                )\n        ){\n\n            return obj[key];\n        }\n    }\n\n\n    return \"\";\n}\n\n\n/* =========================================================\n   COMBINED COLUMNS\n========================================================= */\n\nfunction combinedColumns(\n    obj,\n    aliases\n){\n\n    const values=[];\n\n    const used=\n        new Set();\n\n\n    aliases.forEach(\n        function(alias){\n\n            const key=\n                normalizeText(\n                    alias\n                );\n\n\n            if(\n                used.has(key)\n            ){\n                return;\n            }\n\n\n            used.add(key);\n\n\n            if(\n                Object.prototype\n                    .hasOwnProperty\n                    .call(\n                        obj,\n                        key\n                    )\n            ){\n\n                const value=\n                    clean(\n                        obj[key]\n                    );\n\n\n                if(value){\n\n                    values.push(\n                        value\n                    );\n                }\n            }\n        }\n    );\n\n\n    return values.join(\" \");\n}\n\n\n/* =========================================================\n   FETCH\n========================================================= */\n\nasync function fetchCSV(url){\n\n    const response=\n        await fetch(\n            url,\n            {\n                cache:\n                    \"no-cache\"\n            }\n        );\n\n\n    if(!response.ok){\n\n        throw new Error(\n            \"HTTP \"\n            +\n            response.status\n        );\n    }\n\n\n    return response.text();\n}\n\n\nasync function safeFetchCSV(url){\n\n    try{\n\n        return await fetchCSV(\n            url\n        );\n\n    }catch(error){\n\n        console.warn(\n            \"[OCD Exhibition]\",\n            error\n        );\n\n\n        return \"\";\n    }\n}\n\n\n/* =========================================================\n   DRIVE\n========================================================= */\n\nfunction driveId(v){\n\n    const text=\n        String(v||\"\");\n\n\n    const patterns=[\n\n        /\\/file\\/d\\/([^/?&#]+)/i,\n\n        /\\/d\\/([^/?&#]+)/i,\n\n        /[?&]id=([^&#]+)/i\n\n    ];\n\n\n    for(\n        const pattern\n        of\n        patterns\n    ){\n\n        const match=\n            text.match(\n                pattern\n            );\n\n\n        if(match){\n\n            return match[1];\n        }\n    }\n\n\n    return \"\";\n}\n\n\nfunction firstUrl(v){\n\n    const match=\n        String(v||\"\")\n\n        .match(\n            /https?:\\/\\/[^\\s,]+/i\n        );\n\n\n    return match\n        ?\n        match[0]\n        :\n        \"\";\n}\n\n\nfunction imageUrl(\n    value,\n    size\n){\n\n    if(\n        state.RS\n        &&\n        typeof state.RS.convertDriveImageUrl\n            ===\n            \"function\"\n    ){\n\n        try{\n\n            const converted=\n                state.RS\n                    .convertDriveImageUrl(\n                        value,\n                        size||800\n                    );\n\n\n            if(converted){\n\n                return converted;\n            }\n\n        }catch(error){}\n    }\n\n\n    const id=\n        driveId(value);\n\n\n    if(id){\n\n        return(\n            \"https://drive.google.com/thumbnail?id=\"\n            +\n            encodeURIComponent(id)\n            +\n            \"&sz=w\"\n            +\n            (size||800)\n        );\n    }\n\n\n    return(\n        firstUrl(value)\n        ||\n        clean(value)\n    );\n}\n\n\n/* =========================================================\n   TIME\n========================================================= */\n\nfunction timeValue(v){\n\n    const text=\n        clean(v);\n\n\n    const match=\n        text.match(\n            /^(\\d{1,2})[\\/-](\\d{1,2})[\\/-](\\d{4})(?:[\\s,]+(\\d{1,2}):(\\d{2})(?::(\\d{2}))?)?/\n        );\n\n\n    if(!match){\n\n        return(\n            Date.parse(text)\n            ||\n            0\n        );\n    }\n\n\n    return new Date(\n        +match[3],\n        +match[2]-1,\n        +match[1],\n        +(match[4]||0),\n        +(match[5]||0),\n        +(match[6]||0)\n    ).getTime();\n}\n\n\nfunction compactTimestamp(v){\n\n    const match=\n        String(v||\"\")\n\n        .match(\n            /^(\\d{1,2})[\\/-](\\d{1,2})[\\/-](\\d{4})[\\s,]+(\\d{1,2}):(\\d{2})(?::(\\d{2}))?/\n        );\n\n\n    if(!match){\n\n        return \"\";\n    }\n\n\n    function pad(x){\n\n        return String(x)\n            .padStart(\n                2,\n                \"0\"\n            );\n    }\n\n\n    return(\n        match[3]\n        +\n        pad(match[2])\n        +\n        pad(match[1])\n        +\n        pad(match[4])\n        +\n        pad(match[5])\n        +\n        pad(match[6]||0)\n    );\n}\n\n\n/* =========================================================\n   SUBMISSION ID\n========================================================= */\n\nfunction submissionId(row){\n\n    const existing=\n        clean(\n            column(\n                row,\n                [\n                    \"M\u00e3 b\u00e0i n\u1ed9p\"\n                ]\n            )\n        );\n\n\n    if(existing){\n\n        return existing;\n    }\n\n\n    const timestamp=\n        column(\n            row,\n            [\n                \"D\u1ea5u th\u1eddi gian\"\n            ]\n        );\n\n\n    const code=\n        clean(\n            column(\n                row,\n                [\n                    \"M\u00e3 h\u1ecdc vi\u00ean\"\n                ]\n            )\n        );\n\n\n    const file=\n        column(\n            row,\n            [\n                \"T\u1ea3i b\u00e0i t\u1eadp l\u00ean\"\n            ]\n        );\n\n\n    return(\n        compactTimestamp(\n            timestamp\n        )\n        +\n        \"|\"\n        +\n        code\n        +\n        \"|\"\n        +\n        (\n            driveId(file)\n            ||\n            clean(file)\n        )\n    );\n}\n\n\n/* =========================================================\n   DELETE LOG\n========================================================= */\n\nfunction buildDeletedIds(rows){\n\n    const map=\n        new Map();\n\n\n    (rows||[])\n        .forEach(\n            function(row){\n\n                const id=\n                    clean(\n                        column(\n                            row,\n                            [\n                                \"M\u00e3 b\u00e0i n\u1ed9p\"\n                            ]\n                        )\n                    );\n\n\n                if(!id){\n                    return;\n                }\n\n\n                const action=\n                    normalizeText(\n                        column(\n                            row,\n                            [\n                                \"H\u00e0nh \u0111\u1ed9ng\"\n                            ]\n                        )\n                    );\n\n\n                if(\n                    action.includes(\n                        \"khoi phuc\"\n                    )\n                    ||\n                    action\n                        ===\n                        \"restore\"\n                ){\n\n                    map.set(\n                        id,\n                        false\n                    );\n\n                    return;\n                }\n\n\n                if(\n                    !action\n                    ||\n                    action.includes(\n                        \"xoa\"\n                    )\n                    ||\n                    action\n                        ===\n                        \"delete\"\n                ){\n\n                    map.set(\n                        id,\n                        true\n                    );\n                }\n            }\n        );\n\n\n    state.deletedIds=\n        new Set();\n\n\n    map.forEach(\n        function(\n            deleted,\n            id\n        ){\n\n            if(deleted){\n\n                state.deletedIds\n                    .add(id);\n            }\n        }\n    );\n}\n\n\n/* =========================================================\n   PREPARE WORK\n\n   L\u01afU \u00dd:\n   comment v\u1eabn \u0111\u01b0\u1ee3c \u0111\u1ecdc \u0111\u1ec3 x\u00e9t \u0111i\u1ec1u ki\u1ec7n \"Ngon\",\n   nh\u01b0ng KH\u00d4NG render ra giao di\u1ec7n.\n========================================================= */\n\nfunction prepareWork(row){\n\n    const timestamp=\n        clean(\n            column(\n                row,\n                [\n                    \"D\u1ea5u th\u1eddi gian\"\n                ]\n            )\n        );\n\n\n    const file=\n        column(\n            row,\n            [\n                \"T\u1ea3i b\u00e0i t\u1eadp l\u00ean\"\n            ]\n        );\n\n\n    const assignment=\n        clean(\n            column(\n                row,\n                [\n                    \"M\u00f4 t\u1ea3 b\u00e0i t\u1eadp\",\n                    \"M\u00f4 t\u1ea3\",\n                    \"T\u00ean b\u00e0i t\u1eadp\",\n                    \"B\u00e0i t\u1eadp\",\n                    \"N\u1ed9i dung b\u00e0i t\u1eadp\",\n                    \"T\u00ean b\u00e0i\",\n                    \"Ghi ch\u00fa\"\n                ]\n            )\n        );\n\n\n    const noteText=\n        combinedColumns(\n            row,\n            [\n                \"Ghi ch\u00fa\",\n                \"M\u00f4 t\u1ea3 b\u00e0i t\u1eadp\",\n                \"M\u00f4 t\u1ea3\",\n                \"T\u00ean b\u00e0i t\u1eadp\",\n                \"B\u00e0i t\u1eadp\",\n                \"N\u1ed9i dung b\u00e0i t\u1eadp\",\n                \"T\u00ean b\u00e0i\"\n            ]\n        );\n\n\n    const comment=\n        clean(\n            column(\n                row,\n                [\n                    \"Nh\u1eadn x\u00e9t\",\n                    \"Nh\u1eadn x\u00e9t GVCN\"\n                ]\n            )\n        );\n\n\n    return{\n\n        id:\n            submissionId(row),\n\n        code:\n            normalizeCode(\n                column(\n                    row,\n                    [\n                        \"M\u00e3 h\u1ecdc vi\u00ean\"\n                    ]\n                )\n            ),\n\n        name:\n            clean(\n                column(\n                    row,\n                    [\n                        \"H\u1ecd v\u00e0 t\u00ean\",\n                        \"H\u1ecd t\u00ean\"\n                    ]\n                )\n            ),\n\n        group:\n            clean(\n                column(\n                    row,\n                    [\n                        \"T\u1ed5\"\n                    ]\n                )\n            ),\n\n        course:\n            clean(\n                column(\n                    row,\n                    [\n                        \"Kh\u00f3a\",\n                        \"Khoa\"\n                    ]\n                )\n            ),\n\n        assignment:\n            assignment,\n\n        noteText:\n            noteText,\n\n        timestamp:\n            timestamp,\n\n        time:\n            timeValue(\n                timestamp\n            ),\n\n        file:\n            file,\n\n        originalUrl:\n            firstUrl(file),\n\n        image:\n            imageUrl(\n                file,\n                800\n            ),\n\n        largeImage:\n            imageUrl(\n                file,\n                1800\n            ),\n\n        /*\n           Ch\u1ec9 d\u00f9ng n\u1ed9i b\u1ed9 \u0111\u1ec3 x\u00e9t tri\u1ec3n l\u00e3m.\n           Kh\u00f4ng render ra giao di\u1ec7n.\n        */\n\n        comment:\n            comment,\n\n        sourceRow:\n            Array.isArray(\n                row.__sourceRow\n            )\n            ?\n            row.__sourceRow.slice()\n            :\n            []\n\n    };\n}\n\n\n/* =========================================================\n   EXCLUDED NOTE\n========================================================= */\n\nfunction hasExcludedNote(item){\n\n    const text=\n        normalizeText(\n            [\n                item.assignment,\n                item.noteText\n            ]\n\n            .filter(Boolean)\n\n            .join(\" \")\n        );\n\n\n    if(!text){\n\n        return false;\n    }\n\n\n    return CONFIG.excludedNotes\n\n        .some(\n            function(keyword){\n\n                return text.includes(\n                    keyword\n                );\n            }\n        );\n}\n\n\n/* =========================================================\n   EXHIBITION KEYWORD\n\n   \"Ngon\" ph\u1ea3i xu\u1ea5t hi\u1ec7n nh\u01b0 m\u1ed9t t\u1eeb \u0111\u1ed9c l\u1eadp.\n\n   Nh\u1eadn:\n   - Ngon\n   - ngon\n   - NGON\n   - Ngon!\n   - B\u00e0i n\u00e0y ngon\n   - Kh\u00e1 ngon, ti\u1ebfp t\u1ee5c ph\u00e1t huy\n\n   \u0110\u00e2y ch\u1ec9 l\u00e0 quy t\u1eafc n\u1ed9i b\u1ed9.\n========================================================= */\n\nfunction hasExhibitionKeyword(item){\n\n    const comment=\n        normalizeText(\n            item\n            &&\n            item.comment\n            ?\n            item.comment\n            :\n            \"\"\n        );\n\n\n    if(!comment){\n\n        return false;\n    }\n\n\n    const keyword=\n        normalizeText(\n            CONFIG.exhibitionKeyword\n        );\n\n\n    const words=\n        comment\n\n        .split(\n            /[^a-z0-9]+/\n        )\n\n        .filter(Boolean);\n\n\n    return words.includes(\n        keyword\n    );\n}\n\n\n/* =========================================================\n   EXHIBITION QUALIFICATION\n========================================================= */\n\nfunction isExhibitionWork(item){\n\n    return(\n\n        hasExhibitionKeyword(\n            item\n        )\n\n        &&\n\n        !hasExcludedNote(\n            item\n        )\n\n    );\n}\n\n\n/* =========================================================\n   REWARD CORE READY\n========================================================= */\n\nfunction coreReady(){\n\n    const RS=\n        window.StudentRewardSystem;\n\n\n    return Boolean(\n\n        RS\n\n        &&\n\n        RS.version\n\n        &&\n\n        typeof RS.getStudentRewardProfile\n            ===\n            \"function\"\n\n        &&\n\n        typeof RS.loadSharedRewardData\n            ===\n            \"function\"\n\n    );\n}\n\n\n/* =========================================================\n   WAIT CORE\n========================================================= */\n\nasync function waitForCore(){\n\n    if(coreReady()){\n\n        state.RS=\n            window.StudentRewardSystem;\n\n\n        return state.RS;\n    }\n\n\n    for(\n        let i=0;\n        i<200;\n        i++\n    ){\n\n        await new Promise(\n            function(resolve){\n\n                setTimeout(\n                    resolve,\n                    50\n                );\n            }\n        );\n\n\n        if(coreReady()){\n\n            state.RS=\n                window.StudentRewardSystem;\n\n\n            return state.RS;\n        }\n    }\n\n\n    return null;\n}\n\n\n/* =========================================================\n   CORE CATALOG\n========================================================= */\n\nasync function ensureCoreCatalog(\n    force\n){\n\n    if(\n        state.catalogReady\n        &&\n        !force\n    ){\n\n        return true;\n    }\n\n\n    if(\n        state.catalogPromise\n        &&\n        !force\n    ){\n\n        return state.catalogPromise;\n    }\n\n\n    state.catalogPromise=\n        (\n            async function(){\n\n                const RS=\n                    await waitForCore();\n\n\n                if(!RS){\n\n                    return false;\n                }\n\n\n                try{\n\n                    const shared=\n                        await RS\n                            .loadSharedRewardData(\n                                Boolean(force)\n                            );\n\n\n                    state.giftMap\n                        .clear();\n\n\n                    if(\n                        shared\n                        &&\n                        Array.isArray(\n                            shared.gifts\n                        )\n                    ){\n\n                        shared.gifts\n                            .forEach(\n                                function(gift){\n\n                                    if(\n                                        gift\n                                        &&\n                                        gift.name\n                                    ){\n\n                                        state.giftMap\n                                            .set(\n                                                normalizeReward(\n                                                    gift.name\n                                                ),\n                                                gift\n                                            );\n                                    }\n                                }\n                            );\n                    }\n\n\n                    state.catalogReady=\n                        true;\n\n\n                    return true;\n\n\n                }catch(error){\n\n                    console.warn(\n                        \"[OCD Exhibition Core Catalog]\",\n                        error\n                    );\n\n\n                    return false;\n\n\n                }finally{\n\n                    state.catalogPromise=\n                        null;\n                }\n\n            }\n        )();\n\n\n    return state.catalogPromise;\n}\n\n\n/* =========================================================\n   WORK MAP\n========================================================= */\n\nfunction rebuildWorkMap(){\n\n    state.workMap\n        .clear();\n\n\n    state.allWorks\n        .forEach(\n            function(item){\n\n                const code=\n                    normalizeCode(\n                        item.code\n                    );\n\n\n                if(!code){\n\n                    return;\n                }\n\n\n                if(\n                    !state.workMap\n                        .has(code)\n                ){\n\n                    state.workMap\n                        .set(\n                            code,\n                            []\n                        );\n                }\n\n\n                state.workMap\n                    .get(code)\n                    .push(item);\n            }\n        );\n}\n\n\n/* =========================================================\n   STUDENT WORKS\n========================================================= */\n\nfunction studentWorks(code){\n\n    return(\n        state.workMap\n            .get(\n                normalizeCode(\n                    code\n                )\n            )\n        ||\n        []\n    );\n}\n\n\n/* =========================================================\n   STUDENT SUBMISSION CSV\n========================================================= */\n\nfunction studentSubmissionCsv(code){\n\n    const items=\n        studentWorks(\n            code\n        );\n\n\n    if(\n        !state.workHeader.length\n        ||\n        !items.length\n    ){\n\n        return \"\";\n    }\n\n\n    const rows=[\n        state.workHeader.slice()\n    ];\n\n\n    items.forEach(\n        function(item){\n\n            if(\n                Array.isArray(\n                    item.sourceRow\n                )\n                &&\n                item.sourceRow.length\n            ){\n\n                rows.push(\n                    item.sourceRow.slice()\n                );\n            }\n        }\n    );\n\n\n    return rowsToCsv(\n        rows\n    );\n}\n\n\n/* =========================================================\n   CANONICAL GIFT\n========================================================= */\n\nfunction canonicalGift(name){\n\n    return(\n        state.giftMap\n            .get(\n                normalizeReward(\n                    name\n                )\n            )\n        ||\n        null\n    );\n}\n\n\n/* =========================================================\n   ITEM NAME\n========================================================= */\n\nfunction itemName(item){\n\n    return clean(\n        item\n        &&\n        (\n            item.giftName\n            ||\n            item.name\n            ||\n            (\n                item.gift\n                &&\n                item.gift.name\n            )\n        )\n    );\n}\n\n\n/* =========================================================\n   ITEM QUANTITY\n========================================================= */\n\nfunction itemQuantity(item){\n\n    return Math.max(\n        1,\n        Math.floor(\n            Number(\n                item\n                &&\n                item.quantity\n                ||\n                1\n            )\n            ||\n            1\n        )\n    );\n}\n\n\n/* =========================================================\n   GROUP ITEMS\n========================================================= */\n\nfunction groupItems(items){\n\n    const map=\n        new Map();\n\n\n    (items||[])\n        .forEach(\n            function(item){\n\n                const name=\n                    itemName(\n                        item\n                    );\n\n\n                const key=\n                    normalizeReward(\n                        name\n                    );\n\n\n                if(!key){\n\n                    return;\n                }\n\n\n                if(\n                    !map.has(key)\n                ){\n\n                    map.set(\n                        key,\n                        {\n                            name:\n                                name,\n\n                            quantity:\n                                0,\n\n                            raw:\n                                item\n                        }\n                    );\n                }\n\n\n                map.get(key)\n                    .quantity\n                    +=\n                    itemQuantity(\n                        item\n                    );\n            }\n        );\n\n\n    return Array.from(\n        map.values()\n    );\n}\n\n\n/* =========================================================\n   IS BEAST\n========================================================= */\n\nfunction isBeast(name){\n\n    return normalizeReward(\n        name\n    )\n    .includes(\n        \"linh thu\"\n    );\n}\n\n\n/* =========================================================\n   NORMALIZE CANONICAL ACCOUNT\n========================================================= */\n\nfunction normalizeCanonicalAccount(\n    profile\n){\n\n    const ownedItems=\n        Array.isArray(\n            profile\n            &&\n            profile.ownedItems\n        )\n        ?\n        profile.ownedItems\n        :\n        [];\n\n\n    let avatar=\"\";\n\n    let frame=\"\";\n\n\n    if(\n        profile\n        &&\n        profile.avatar\n    ){\n\n        avatar=\n            profile.avatar;\n\n\n    }else if(\n        state.RS\n        &&\n        typeof state.RS.getProfileAvatar\n            ===\n            \"function\"\n    ){\n\n        try{\n\n            avatar=\n                state.RS\n                    .getProfileAvatar(\n                        ownedItems\n                    )\n                ||\n                \"\";\n\n        }catch(error){}\n    }\n\n\n    if(\n        profile\n        &&\n        (\n            profile.avatarFrame\n            ||\n            profile.frame\n        )\n    ){\n\n        frame=\n            profile.avatarFrame\n            ||\n            profile.frame;\n\n\n    }else if(\n        state.RS\n        &&\n        typeof state.RS.getProfileAvatarFrame\n            ===\n            \"function\"\n    ){\n\n        try{\n\n            frame=\n                state.RS\n                    .getProfileAvatarFrame(\n                        ownedItems\n                    )\n                ||\n                \"\";\n\n        }catch(error){}\n    }\n\n\n    return{\n\n        profile:\n            profile,\n\n        ownedItems:\n            ownedItems,\n\n        avatar:\n            avatar,\n\n        frame:\n            frame\n\n    };\n}\n\n\n/* =========================================================\n   GET ACCOUNT\n========================================================= */\n\nasync function getAccount(\n    code,\n    force\n){\n\n    const normalized=\n        normalizeCode(\n            code\n        );\n\n\n    if(!normalized){\n\n        return null;\n    }\n\n\n    if(\n        !force\n        &&\n        state.accountMap\n            .has(normalized)\n    ){\n\n        return state.accountMap\n            .get(normalized);\n    }\n\n\n    if(\n        !force\n        &&\n        state.accountPromiseMap\n            .has(normalized)\n    ){\n\n        return state.accountPromiseMap\n            .get(normalized);\n    }\n\n\n    const promise=\n        (\n            async function(){\n\n                const ready=\n                    await ensureCoreCatalog(\n                        Boolean(force)\n                    );\n\n\n                if(\n                    !ready\n                    ||\n                    !state.RS\n                ){\n\n                    return null;\n                }\n\n\n                const submissionCsv=\n                    studentSubmissionCsv(\n                        normalized\n                    );\n\n\n                const profile=\n                    await state.RS\n                        .getStudentRewardProfile(\n                            normalized,\n                            submissionCsv,\n                            Boolean(force)\n                        );\n\n\n                if(!profile){\n\n                    return null;\n                }\n\n\n                const account=\n                    normalizeCanonicalAccount(\n                        profile\n                    );\n\n\n                state.accountMap\n                    .set(\n                        normalized,\n                        account\n                    );\n\n\n                return account;\n\n            }\n        )()\n\n        .catch(\n            function(error){\n\n                console.warn(\n                    \"[OCD Exhibition Account]\",\n                    normalized,\n                    error\n                );\n\n\n                return null;\n            }\n        )\n\n        .finally(\n            function(){\n\n                state.accountPromiseMap\n                    .delete(\n                        normalized\n                    );\n            }\n        );\n\n\n    state.accountPromiseMap\n        .set(\n            normalized,\n            promise\n        );\n\n\n    return promise;\n}\n\n\n/* =========================================================\n   BEAST ITEMS\n========================================================= */\n\nfunction beastItems(account){\n\n    if(\n        !account\n        ||\n        !Array.isArray(\n            account.ownedItems\n        )\n    ){\n\n        return [];\n    }\n\n\n    return groupItems(\n        account.ownedItems\n    )\n    .filter(\n        function(item){\n\n            return isBeast(\n                item.name\n            );\n        }\n    );\n}\n\n\n/* =========================================================\n   GIFT IMAGE\n========================================================= */\n\nfunction giftImage(name){\n\n    const gift=\n        canonicalGift(\n            name\n        );\n\n\n    if(!gift){\n\n        return \"\";\n    }\n\n\n    return(\n        gift.image\n        ||\n        gift.icon\n        ||\n        \"\"\n    );\n}\n\n\n/* =========================================================\n   AVATAR LETTER\n========================================================= */\n\nfunction avatarLetter(name){\n\n    const text=\n        clean(name);\n\n\n    if(!text){\n\n        return \"H\";\n    }\n\n\n    const words=\n        text\n\n        .split(/\\s+/)\n\n        .filter(Boolean);\n\n\n    const last=\n        words[\n            words.length-1\n        ]\n        ||\n        text;\n\n\n    return last\n        .charAt(0)\n        .toUpperCase();\n}\n\n\n/* =========================================================\n   RENDER AVATAR\n========================================================= */\n\nfunction renderAvatar(\n    account,\n    item,\n    avatarCore,\n    avatarWrap\n){\n\n    if(\n        !avatarCore\n        ||\n        !avatarCore.isConnected\n    ){\n\n        return;\n    }\n\n\n    avatarCore.innerHTML=\"\";\n\n\n    const avatar=\n        account\n        &&\n        account.avatar\n        ?\n        imageUrl(\n            account.avatar,\n            160\n        )\n        :\n        \"\";\n\n\n    if(avatar){\n\n        const img=\n            document.createElement(\n                \"img\"\n            );\n\n\n        img.src=\n            avatar;\n\n\n        img.alt=\n            item.name\n            ||\n            \"H\u1ecdc vi\u00ean\";\n\n\n        img.loading=\n            \"lazy\";\n\n\n        img.decoding=\n            \"async\";\n\n\n        img.onerror=\n            function(){\n\n                img.remove();\n\n\n                const fallback=\n                    document.createElement(\n                        \"span\"\n                    );\n\n\n                fallback.className=\n                    \"ex-avatar-fallback\";\n\n\n                fallback.textContent=\n                    avatarLetter(\n                        item.name\n                    );\n\n\n                avatarCore\n                    .appendChild(\n                        fallback\n                    );\n            };\n\n\n        avatarCore\n            .appendChild(\n                img\n            );\n\n\n    }else{\n\n        const fallback=\n            document.createElement(\n                \"span\"\n            );\n\n\n        fallback.className=\n            \"ex-avatar-fallback\";\n\n\n        fallback.textContent=\n            avatarLetter(\n                item.name\n            );\n\n\n        avatarCore\n            .appendChild(\n                fallback\n            );\n    }\n\n\n    const oldFrame=\n        avatarWrap\n            .querySelector(\n                \".ex-avatar-frame\"\n            );\n\n\n    if(oldFrame){\n\n        oldFrame.remove();\n    }\n\n\n    const frame=\n        account\n        &&\n        account.frame\n        ?\n        imageUrl(\n            account.frame,\n            180\n        )\n        :\n        \"\";\n\n\n    if(frame){\n\n        const frameImg=\n            document.createElement(\n                \"img\"\n            );\n\n\n        frameImg.className=\n            \"ex-avatar-frame\";\n\n\n        frameImg.src=\n            frame;\n\n\n        frameImg.alt=\n            \"\";\n\n\n        frameImg.loading=\n            \"lazy\";\n\n\n        frameImg.decoding=\n            \"async\";\n\n\n        frameImg.onerror=\n            function(){\n\n                frameImg.remove();\n            };\n\n\n        avatarWrap\n            .appendChild(\n                frameImg\n            );\n    }\n}\n\n\n/* =========================================================\n   CREATE BEAST\n========================================================= */\n\nfunction createBeast(\n    item,\n    index\n){\n\n    const source=\n        giftImage(\n            item.name\n        );\n\n\n    if(!source){\n\n        return null;\n    }\n\n\n    const holder=\n        document.createElement(\n            \"div\"\n        );\n\n\n    holder.className=\n        \"ex-footer-beast\";\n\n\n    holder.title=\n        item.name;\n\n\n    holder.setAttribute(\n        \"aria-label\",\n        item.name\n    );\n\n\n    holder.style.animationDelay=\n        String(\n            -(index*.55)\n        )\n        +\n        \"s\";\n\n\n    const img=\n        document.createElement(\n            \"img\"\n        );\n\n\n    img.className=\n        \"ex-footer-beast-image\";\n\n\n    img.src=\n        imageUrl(\n            source,\n            190\n        );\n\n\n    img.alt=\n        item.name;\n\n\n    img.loading=\n        \"lazy\";\n\n\n    img.decoding=\n        \"async\";\n\n\n    img.style.animationDelay=\n        String(\n            -(index*.8)\n        )\n        +\n        \"s\";\n\n\n    img.onerror=\n        function(){\n\n            holder.remove();\n        };\n\n\n    holder\n        .appendChild(\n            img\n        );\n\n\n    return holder;\n}\n\n\n/* =========================================================\n   RENDER BEAST LIST\n========================================================= */\n\nfunction renderBeastList(\n    account,\n    container\n){\n\n    if(!container){\n\n        return;\n    }\n\n\n    container.innerHTML=\"\";\n\n\n    container.classList\n        .remove(\n            \"visible\"\n        );\n\n\n    const beasts=\n        beastItems(\n            account\n        )\n        .slice(\n            0,\n            CONFIG.maxBeastsPerCard\n        );\n\n\n    beasts.forEach(\n        function(\n            beast,\n            index\n        ){\n\n            const node=\n                createBeast(\n                    beast,\n                    index\n                );\n\n\n            if(node){\n\n                container\n                    .appendChild(\n                        node\n                    );\n            }\n        }\n    );\n\n\n    if(\n        container.children.length\n    ){\n\n        container.classList\n            .add(\n                \"visible\"\n            );\n    }\n}\n\n\n/* =========================================================\n   HYDRATE STUDENT ASSETS\n========================================================= */\n\nasync function hydrateStudentAssets(\n    item,\n    avatarWrap,\n    avatarCore,\n    beastsWrap\n){\n\n    if(!item.code){\n\n        return;\n    }\n\n\n    const account=\n        await getAccount(\n            item.code,\n            false\n        );\n\n\n    if(\n        !avatarWrap\n        ||\n        !avatarWrap.isConnected\n    ){\n\n        return;\n    }\n\n\n    if(!account){\n\n        return;\n    }\n\n\n    renderAvatar(\n        account,\n        item,\n        avatarCore,\n        avatarWrap\n    );\n\n\n    if(\n        beastsWrap\n        &&\n        beastsWrap.isConnected\n    ){\n\n        renderBeastList(\n            account,\n            beastsWrap\n        );\n    }\n}\n\n\n/* =========================================================\n   HYDRATE LIGHTBOX BEASTS\n========================================================= */\n\nasync function hydrateLightboxBeasts(\n    item,\n    token\n){\n\n    const container=\n        el(\n            \"exLightboxBeasts\"\n        );\n\n\n    if(!container){\n\n        return;\n    }\n\n\n    container.innerHTML=\"\";\n\n\n    container.classList\n        .remove(\n            \"visible\"\n        );\n\n\n    if(\n        !item\n        ||\n        !item.code\n    ){\n\n        return;\n    }\n\n\n    const account=\n        await getAccount(\n            item.code,\n            false\n        );\n\n\n    if(\n        token\n        !==\n        state.lightboxToken\n\n        ||\n\n        state.activeLightbox\n        !==\n        item\n\n        ||\n\n        !container.isConnected\n    ){\n\n        return;\n    }\n\n\n    if(!account){\n\n        return;\n    }\n\n\n    renderBeastList(\n        account,\n        container\n    );\n}\n\n\n/* =========================================================\n   LOAD WORK SOURCE\n========================================================= */\n\nasync function loadWorkSource(){\n\n    try{\n\n        const text=\n            await fetchCSV(\n                CONFIG.works\n            );\n\n\n        const rows=\n            parseCSV(\n                text\n            );\n\n\n        if(\n            rows.length>1\n        ){\n\n            return{\n\n                text:\n                    text,\n\n                rows:\n                    rows,\n\n                objects:\n                    csvObjectsFromRows(\n                        rows\n                    )\n\n            };\n        }\n\n    }catch(error){\n\n        console.warn(\n            \"[OCD Exhibition Primary Works]\",\n            error\n        );\n    }\n\n\n    const fallback=\n        await fetchCSV(\n            CONFIG.fallback\n        );\n\n\n    const rows=\n        parseCSV(\n            fallback\n        );\n\n\n    return{\n\n        text:\n            fallback,\n\n        rows:\n            rows,\n\n        objects:\n            csvObjectsFromRows(\n                rows\n            )\n\n    };\n}\n\n\n/* =========================================================\n   LOAD DATA\n========================================================= */\n\nasync function loadData(){\n\n    if(state.loading){\n\n        return;\n    }\n\n\n    state.loading=\n        true;\n\n\n    el(\"exLoading\")\n        .classList\n        .add(\n            \"visible\"\n        );\n\n\n    el(\"exError\")\n        .classList\n        .remove(\n            \"visible\"\n        );\n\n\n    el(\"exEmpty\")\n        .classList\n        .remove(\n            \"visible\"\n        );\n\n\n    try{\n\n        const results=\n            await Promise.all([\n\n                loadWorkSource(),\n\n                safeFetchCSV(\n                    CONFIG.deleteLog\n                )\n\n            ]);\n\n\n        const source=\n            results[0];\n\n\n        state.workHeader=\n            source.rows\n            &&\n            source.rows[0]\n            ?\n            source.rows[0].slice()\n            :\n            [];\n\n\n        if(results[1]){\n\n            buildDeletedIds(\n                csvObjects(\n                    results[1]\n                )\n            );\n\n\n        }else{\n\n            state.deletedIds=\n                new Set();\n        }\n\n\n        state.allWorks=\n            source.objects\n\n            .filter(\n                function(row){\n\n                    return(\n                        !state.deletedIds\n                            .has(\n                                submissionId(\n                                    row\n                                )\n                            )\n                    );\n                }\n            )\n\n            .map(\n                prepareWork\n            )\n\n            .sort(\n                function(a,b){\n\n                    return(\n                        (b.time||0)\n                        -\n                        (a.time||0)\n                    );\n                }\n            );\n\n\n        rebuildWorkMap();\n\n\n        /* =================================================\n           TRI\u1ec2N L\u00c3M v1.4.0\n\n           \u0110i\u1ec1u ki\u1ec7n:\n           - Nh\u1eadn x\u00e9t GVCN ch\u1ee9a t\u1eeb \"Ngon\"\n           - Kh\u00f4ng x\u00e9t \u0111i\u1ec3m\n           - Kh\u00f4ng hi\u1ec3n th\u1ecb nh\u1eadn x\u00e9t\n           - Kh\u00f4ng hi\u1ec3n th\u1ecb \u0111i\u1ec3m\n        ================================================= */\n\n        state.exhibitionWorks=\n            state.allWorks\n\n            .filter(\n                function(item){\n\n                    return isExhibitionWork(\n                        item\n                    );\n                }\n            )\n\n            .sort(\n                function(a,b){\n\n                    return(\n                        (b.time||0)\n                        -\n                        (a.time||0)\n                    );\n                }\n            );\n\n\n        populateFilters();\n\n\n        renderStats();\n\n\n        applyFilters(\n            false\n        );\n\n\n        ensureCoreCatalog(\n            false\n        )\n        .catch(\n            function(error){\n\n                console.warn(\n                    \"[OCD Exhibition Core Warmup]\",\n                    error\n                );\n            }\n        );\n\n\n        console.info(\n            \"[OCD Exhibition] v\"\n            +\n            CONFIG.version\n            +\n            \" ready | \"\n            +\n            state.exhibitionWorks.length\n            +\n            \" exhibition works\"\n        );\n\n\n    }catch(error){\n\n        console.error(\n            \"[OCD Exhibition]\",\n            error\n        );\n\n\n        el(\"exError\")\n            .textContent=\n            \"Kh\u00f4ng t\u1ea3i \u0111\u01b0\u1ee3c Ph\u00f2ng tri\u1ec3n l\u00e3m: \"\n            +\n            (\n                error.message\n                ||\n                error\n            );\n\n\n        el(\"exError\")\n            .classList\n            .add(\n                \"visible\"\n            );\n\n\n    }finally{\n\n        state.loading=\n            false;\n\n\n        el(\"exLoading\")\n            .classList\n            .remove(\n                \"visible\"\n            );\n    }\n}\n\n\n/* =========================================================\n   UNIQUE\n========================================================= */\n\nfunction uniqueValues(\n    items,\n    key\n){\n\n    const map=\n        new Map();\n\n\n    items.forEach(\n        function(item){\n\n            const value=\n                clean(\n                    item[key]\n                );\n\n\n            if(!value){\n\n                return;\n            }\n\n\n            const normalized=\n                normalizeText(\n                    value\n                );\n\n\n            if(\n                !map.has(\n                    normalized\n                )\n            ){\n\n                map.set(\n                    normalized,\n                    value\n                );\n            }\n        }\n    );\n\n\n    return Array.from(\n        map.values()\n    )\n\n    .sort(\n        function(a,b){\n\n            return String(a)\n                .localeCompare(\n                    String(b),\n                    \"vi\",\n                    {\n                        numeric:true,\n                        sensitivity:\"base\"\n                    }\n                );\n        }\n    );\n}\n\n\n/* =========================================================\n   FILTER OPTIONS\n========================================================= */\n\nfunction populateFilters(){\n\n    const course=\n        el(\n            \"exCourse\"\n        );\n\n\n    const group=\n        el(\n            \"exGroup\"\n        );\n\n\n    course.innerHTML=\"\";\n\n    group.innerHTML=\"\";\n\n\n    const courseAll=\n        document.createElement(\n            \"option\"\n        );\n\n\n    courseAll.value=\"\";\n\n    courseAll.textContent=\n        \"T\u1ea5t c\u1ea3 kh\u00f3a\";\n\n\n    course.appendChild(\n        courseAll\n    );\n\n\n    const groupAll=\n        document.createElement(\n            \"option\"\n        );\n\n\n    groupAll.value=\"\";\n\n    groupAll.textContent=\n        \"T\u1ea5t c\u1ea3 t\u1ed5\";\n\n\n    group.appendChild(\n        groupAll\n    );\n\n\n    uniqueValues(\n        state.exhibitionWorks,\n        \"course\"\n    )\n    .forEach(\n        function(value){\n\n            const option=\n                document.createElement(\n                    \"option\"\n                );\n\n\n            option.value=\n                value;\n\n\n            option.textContent=\n                \"Kh\u00f3a \"\n                +\n                value;\n\n\n            course.appendChild(\n                option\n            );\n        }\n    );\n\n\n    uniqueValues(\n        state.exhibitionWorks,\n        \"group\"\n    )\n    .forEach(\n        function(value){\n\n            const option=\n                document.createElement(\n                    \"option\"\n                );\n\n\n            option.value=\n                value;\n\n\n            option.textContent=\n                \"T\u1ed5 \"\n                +\n                value;\n\n\n            group.appendChild(\n                option\n            );\n        }\n    );\n}\n\n\n/* =========================================================\n   STATS\n========================================================= */\n\nfunction renderStats(){\n\n    const works=\n        state.exhibitionWorks;\n\n\n    const students=\n        new Set();\n\n\n    const groups=\n        new Set();\n\n\n    const courses=\n        new Set();\n\n\n    works.forEach(\n        function(item){\n\n            if(item.code){\n\n                students.add(\n                    normalizeCode(\n                        item.code\n                    )\n                );\n            }\n\n\n            if(item.group){\n\n                groups.add(\n                    normalizeText(\n                        item.group\n                    )\n                );\n            }\n\n\n            if(item.course){\n\n                courses.add(\n                    normalizeText(\n                        item.course\n                    )\n                );\n            }\n        }\n    );\n\n\n    el(\"exStatWorks\")\n        .textContent=\n        String(\n            works.length\n        );\n\n\n    el(\"exStatStudents\")\n        .textContent=\n        String(\n            students.size\n        );\n\n\n    el(\"exStatGroups\")\n        .textContent=\n        String(\n            groups.size\n        );\n\n\n    el(\"exStatCourses\")\n        .textContent=\n        String(\n            courses.size\n        );\n}\n\n\n/* =========================================================\n   PAGE SIZE\n========================================================= */\n\nfunction pageSize(){\n\n    return window\n        .matchMedia(\n            \"(max-width:700px)\"\n        )\n        .matches\n\n        ?\n\n        CONFIG.mobilePageSize\n\n        :\n\n        CONFIG.desktopPageSize;\n}\n\n\n/* =========================================================\n   APPLY FILTER\n========================================================= */\n\nfunction applyFilters(\n    resetPage\n){\n\n    if(\n        resetPage!==false\n    ){\n\n        state.page=1;\n    }\n\n\n    const query=\n        normalizeText(\n            el(\"exSearch\")\n                .value\n        );\n\n\n    const course=\n        normalizeText(\n            el(\"exCourse\")\n                .value\n        );\n\n\n    const group=\n        normalizeText(\n            el(\"exGroup\")\n                .value\n        );\n\n\n    const sort=\n        el(\"exSort\")\n            .value;\n\n\n    let items=\n        state.exhibitionWorks\n\n        .filter(\n            function(item){\n\n                if(query){\n\n                    const haystack=\n                        normalizeText(\n                            [\n                                item.name,\n                                item.assignment,\n                                item.group,\n                                item.course\n                            ]\n                            .join(\" \")\n                        );\n\n\n                    if(\n                        !haystack.includes(\n                            query\n                        )\n                    ){\n\n                        return false;\n                    }\n                }\n\n\n                if(\n                    course\n                    &&\n                    normalizeText(\n                        item.course\n                    )\n                    !==\n                    course\n                ){\n\n                    return false;\n                }\n\n\n                if(\n                    group\n                    &&\n                    normalizeText(\n                        item.group\n                    )\n                    !==\n                    group\n                ){\n\n                    return false;\n                }\n\n\n                return true;\n            }\n        );\n\n\n    items=\n        items.slice();\n\n\n    if(\n        sort===\"oldest\"\n    ){\n\n        items.sort(\n            function(a,b){\n\n                return(\n                    (a.time||0)\n                    -\n                    (b.time||0)\n                );\n            }\n        );\n\n\n    }else{\n\n        items.sort(\n            function(a,b){\n\n                return(\n                    (b.time||0)\n                    -\n                    (a.time||0)\n                );\n            }\n        );\n    }\n\n\n    state.filteredWorks=\n        items;\n\n\n    normalizePage();\n\n\n    renderGallery();\n\n\n    renderPages();\n\n\n    renderResultText();\n}\n\n\n/* =========================================================\n   PAGE\n========================================================= */\n\nfunction pageCount(){\n\n    return Math.max(\n        1,\n        Math.ceil(\n            state.filteredWorks.length\n            /\n            pageSize()\n        )\n    );\n}\n\n\nfunction normalizePage(){\n\n    const total=\n        pageCount();\n\n\n    if(\n        state.page<1\n    ){\n\n        state.page=1;\n    }\n\n\n    if(\n        state.page>total\n    ){\n\n        state.page=\n            total;\n    }\n}\n\n\nfunction currentWorks(){\n\n    normalizePage();\n\n\n    const size=\n        pageSize();\n\n\n    const start=\n        (\n            state.page\n            -\n            1\n        )\n        *\n        size;\n\n\n    return state.filteredWorks\n        .slice(\n            start,\n            start+size\n        );\n}\n\n\n/* =========================================================\n   FALLBACK IMAGE\n========================================================= */\n\nfunction noImage(){\n\n    const box=\n        document.createElement(\n            \"div\"\n        );\n\n\n    box.className=\n        \"ex-no-image\";\n\n\n    const icon=\n        document.createElement(\n            \"div\"\n        );\n\n\n    icon.className=\n        \"ex-no-image-icon\";\n\n\n    icon.textContent=\n        String.fromCodePoint(\n            0x25A7\n        );\n\n\n    const text=\n        document.createElement(\n            \"div\"\n        );\n\n\n    text.className=\n        \"ex-no-image-text\";\n\n\n    text.textContent=\n        \"Kh\u00f4ng t\u1ea3i \u0111\u01b0\u1ee3c \u1ea3nh\";\n\n\n    box.append(\n        icon,\n        text\n    );\n\n\n    return box;\n}\n\n\n/* =========================================================\n   CHIP\n========================================================= */\n\nfunction createChip(text){\n\n    const chip=\n        document.createElement(\n            \"span\"\n        );\n\n\n    chip.className=\n        \"ex-chip\";\n\n\n    chip.textContent=\n        text;\n\n\n    return chip;\n}\n\n\n/* =========================================================\n   CARD\n\n   KH\u00d4NG C\u00d3:\n   - \u0110i\u1ec3m\n   - Nh\u1eadn x\u00e9t GVCN\n========================================================= */\n\nfunction createCard(\n    item,\n    localIndex\n){\n\n    const card=\n        document.createElement(\n            \"article\"\n        );\n\n\n    card.className=\n        \"ex-card\";\n\n\n    /* IMAGE */\n\n    const imageBox=\n        document.createElement(\n            \"div\"\n        );\n\n\n    imageBox.className=\n        \"ex-image-box\";\n\n\n    if(item.image){\n\n        const img=\n            document.createElement(\n                \"img\"\n            );\n\n\n        img.className=\n            \"ex-image\";\n\n\n        img.src=\n            item.image;\n\n\n        img.alt=\n            item.assignment\n            ?\n            (\n                item.assignment\n                +\n                \" - \"\n                +\n                (\n                    item.name\n                    ||\n                    \"H\u1ecdc vi\u00ean\"\n                )\n            )\n            :\n            (\n                \"T\u00e1c ph\u1ea9m c\u1ee7a \"\n                +\n                (\n                    item.name\n                    ||\n                    \"h\u1ecdc vi\u00ean\"\n                )\n            );\n\n\n        img.loading=\n            localIndex<2\n            ?\n            \"eager\"\n            :\n            \"lazy\";\n\n\n        img.decoding=\n            \"async\";\n\n\n        img.onerror=\n            function(){\n\n                img.remove();\n\n\n                imageBox\n                    .appendChild(\n                        noImage()\n                    );\n            };\n\n\n        imageBox\n            .appendChild(\n                img\n            );\n\n\n        imageBox\n            .addEventListener(\n                \"click\",\n                function(){\n\n                    openLightbox(\n                        item\n                    );\n                }\n            );\n\n\n    }else{\n\n        imageBox\n            .appendChild(\n                noImage()\n            );\n    }\n\n\n    card.appendChild(\n        imageBox\n    );\n\n\n    /* BODY */\n\n    const body=\n        document.createElement(\n            \"div\"\n        );\n\n\n    body.className=\n        \"ex-card-body\";\n\n\n    /* STUDENT HEADER */\n\n    const studentHeader=\n        document.createElement(\n            \"div\"\n        );\n\n\n    studentHeader.className=\n        \"ex-student-header\";\n\n\n    /* AVATAR */\n\n    const avatarWrap=\n        document.createElement(\n            \"div\"\n        );\n\n\n    avatarWrap.className=\n        \"ex-avatar\";\n\n\n    const avatarCore=\n        document.createElement(\n            \"div\"\n        );\n\n\n    avatarCore.className=\n        \"ex-avatar-core\";\n\n\n    const avatarFallback=\n        document.createElement(\n            \"span\"\n        );\n\n\n    avatarFallback.className=\n        \"ex-avatar-fallback\";\n\n\n    avatarFallback.textContent=\n        avatarLetter(\n            item.name\n        );\n\n\n    avatarCore\n        .appendChild(\n            avatarFallback\n        );\n\n\n    avatarWrap\n        .appendChild(\n            avatarCore\n        );\n\n\n    /* STUDENT INFO */\n\n    const studentInfo=\n        document.createElement(\n            \"div\"\n        );\n\n\n    studentInfo.className=\n        \"ex-student-info\";\n\n\n    const author=\n        document.createElement(\n            \"div\"\n        );\n\n\n    author.className=\n        \"ex-author\";\n\n\n    author.textContent=\n        item.name\n        ||\n        \"H\u1ecdc vi\u00ean\";\n\n\n    studentInfo\n        .appendChild(\n            author\n        );\n\n\n    if(item.assignment){\n\n        const assignment=\n            document.createElement(\n                \"div\"\n            );\n\n\n        assignment.className=\n            \"ex-assignment\";\n\n\n        assignment.textContent=\n            item.assignment;\n\n\n        studentInfo\n            .appendChild(\n                assignment\n            );\n    }\n\n\n    studentHeader.append(\n        avatarWrap,\n        studentInfo\n    );\n\n\n    body.appendChild(\n        studentHeader\n    );\n\n\n    /* META */\n\n    const meta=\n        document.createElement(\n            \"div\"\n        );\n\n\n    meta.className=\n        \"ex-meta\";\n\n\n    if(item.group){\n\n        meta.appendChild(\n            createChip(\n                \"T\u1ed5 \"\n                +\n                item.group\n            )\n        );\n    }\n\n\n    if(item.course){\n\n        meta.appendChild(\n            createChip(\n                \"Kh\u00f3a \"\n                +\n                item.course\n            )\n        );\n    }\n\n\n    if(\n        meta.children.length\n    ){\n\n        body.appendChild(\n            meta\n        );\n    }\n\n\n    /* FOOTER */\n\n    const footer=\n        document.createElement(\n            \"div\"\n        );\n\n\n    footer.className=\n        \"ex-card-footer\";\n\n\n    const footerLeft=\n        document.createElement(\n            \"div\"\n        );\n\n\n    footerLeft.className=\n        \"ex-footer-left\";\n\n\n    const time=\n        document.createElement(\n            \"span\"\n        );\n\n\n    time.className=\n        \"ex-time\";\n\n\n    time.textContent=\n        item.timestamp\n        ||\n        \"-\";\n\n\n    footerLeft\n        .appendChild(\n            time\n        );\n\n\n    const beastsWrap=\n        document.createElement(\n            \"div\"\n        );\n\n\n    beastsWrap.className=\n        \"ex-footer-beasts\";\n\n\n    footerLeft\n        .appendChild(\n            beastsWrap\n        );\n\n\n    const view=\n        document.createElement(\n            \"button\"\n        );\n\n\n    view.type=\n        \"button\";\n\n\n    view.className=\n        \"ex-view\";\n\n\n    view.textContent=\n        \"Xem t\u00e1c ph\u1ea9m\";\n\n\n    view.addEventListener(\n        \"click\",\n        function(){\n\n            openLightbox(\n                item\n            );\n        }\n    );\n\n\n    footer.append(\n        footerLeft,\n        view\n    );\n\n\n    body.appendChild(\n        footer\n    );\n\n\n    card.appendChild(\n        body\n    );\n\n\n    /* ASSETS */\n\n    hydrateStudentAssets(\n        item,\n        avatarWrap,\n        avatarCore,\n        beastsWrap\n    )\n    .catch(\n        function(error){\n\n            console.warn(\n                \"[OCD Exhibition Assets]\",\n                error\n            );\n        }\n    );\n\n\n    return card;\n}\n\n\n/* =========================================================\n   RENDER GALLERY\n========================================================= */\n\nfunction renderGallery(){\n\n    const grid=\n        el(\n            \"exGrid\"\n        );\n\n\n    grid.innerHTML=\"\";\n\n\n    const items=\n        currentWorks();\n\n\n    if(\n        !items.length\n    ){\n\n        el(\"exEmpty\")\n            .classList\n            .add(\n                \"visible\"\n            );\n\n\n        return;\n    }\n\n\n    el(\"exEmpty\")\n        .classList\n        .remove(\n            \"visible\"\n        );\n\n\n    const fragment=\n        document\n            .createDocumentFragment();\n\n\n    items.forEach(\n        function(\n            item,\n            index\n        ){\n\n            fragment\n                .appendChild(\n                    createCard(\n                        item,\n                        index\n                    )\n                );\n        }\n    );\n\n\n    grid.appendChild(\n        fragment\n    );\n}\n\n\n/* =========================================================\n   RESULT TEXT\n========================================================= */\n\nfunction renderResultText(){\n\n    const total=\n        state.filteredWorks\n            .length;\n\n\n    const box=\n        el(\n            \"exResultText\"\n        );\n\n\n    box.textContent=\"\";\n\n\n    if(!total){\n\n        box.textContent=\n            \"Kh\u00f4ng c\u00f3 t\u00e1c ph\u1ea9m ph\u00f9 h\u1ee3p v\u1edbi b\u1ed9 l\u1ecdc hi\u1ec7n t\u1ea1i.\";\n\n\n        return;\n    }\n\n\n    const size=\n        pageSize();\n\n\n    const start=\n        (\n            state.page\n            -\n            1\n        )\n        *\n        size\n        +\n        1;\n\n\n    const end=\n        Math.min(\n            state.page\n            *\n            size,\n            total\n        );\n\n\n    box.appendChild(\n        document.createTextNode(\n            \"\u0110ang xem \"\n        )\n    );\n\n\n    const first=\n        document.createElement(\n            \"strong\"\n        );\n\n\n    first.textContent=\n        String(start)\n        +\n        CHAR.dash\n        +\n        String(end);\n\n\n    box.appendChild(\n        first\n    );\n\n\n    box.appendChild(\n        document.createTextNode(\n            \" trong \"\n        )\n    );\n\n\n    const second=\n        document.createElement(\n            \"strong\"\n        );\n\n\n    second.textContent=\n        String(total);\n\n\n    box.appendChild(\n        second\n    );\n\n\n    box.appendChild(\n        document.createTextNode(\n            \" t\u00e1c ph\u1ea9m tri\u1ec3n l\u00e3m.\"\n        )\n    );\n}\n\n\n/* =========================================================\n   PAGINATION\n========================================================= */\n\nfunction renderPages(){\n\n    const container=\n        el(\n            \"exPages\"\n        );\n\n\n    container.innerHTML=\"\";\n\n\n    const total=\n        pageCount();\n\n\n    if(\n        total<=1\n        ||\n        !state.filteredWorks.length\n    ){\n\n        container.classList\n            .remove(\n                \"visible\"\n            );\n\n\n        return;\n    }\n\n\n    container.classList\n        .add(\n            \"visible\"\n        );\n\n\n    /* PREVIOUS */\n\n    const previous=\n        document.createElement(\n            \"button\"\n        );\n\n\n    previous.type=\n        \"button\";\n\n\n    previous.className=\n        \"ex-page\";\n\n\n    previous.textContent=\n        CHAR.previous;\n\n\n    previous.setAttribute(\n        \"aria-label\",\n        \"Trang tr\u01b0\u1edbc\"\n    );\n\n\n    previous.disabled=\n        state.page===1;\n\n\n    previous.addEventListener(\n        \"click\",\n        function(){\n\n            if(\n                state.page<=1\n            ){\n\n                return;\n            }\n\n\n            goPage(\n                state.page-1\n            );\n        }\n    );\n\n\n    container.appendChild(\n        previous\n    );\n\n\n    /* PAGE NUMBERS */\n\n    const pages=[];\n\n\n    function addPage(page){\n\n        if(\n            page>=1\n            &&\n            page<=total\n            &&\n            !pages.includes(\n                page\n            )\n        ){\n\n            pages.push(\n                page\n            );\n        }\n    }\n\n\n    addPage(1);\n\n    addPage(\n        state.page-2\n    );\n\n    addPage(\n        state.page-1\n    );\n\n    addPage(\n        state.page\n    );\n\n    addPage(\n        state.page+1\n    );\n\n    addPage(\n        state.page+2\n    );\n\n    addPage(total);\n\n\n    pages.sort(\n        function(a,b){\n\n            return a-b;\n        }\n    );\n\n\n    let previousPage=\n        0;\n\n\n    pages.forEach(\n        function(page){\n\n            if(\n                previousPage\n                &&\n                page\n                -\n                previousPage\n                >\n                1\n            ){\n\n                const dots=\n                    document.createElement(\n                        \"span\"\n                    );\n\n\n                dots.className=\n                    \"ex-page-dots\";\n\n\n                dots.textContent=\n                    CHAR.ellipsis;\n\n\n                container\n                    .appendChild(\n                        dots\n                    );\n            }\n\n\n            const button=\n                document.createElement(\n                    \"button\"\n                );\n\n\n            button.type=\n                \"button\";\n\n\n            button.className=\n                \"ex-page\"\n                +\n                (\n                    page\n                    ===\n                    state.page\n                    ?\n                    \" active\"\n                    :\n                    \"\"\n                );\n\n\n            button.textContent=\n                String(page);\n\n\n            button.addEventListener(\n                \"click\",\n                function(){\n\n                    goPage(\n                        page\n                    );\n                }\n            );\n\n\n            container.appendChild(\n                button\n            );\n\n\n            previousPage=\n                page;\n        }\n    );\n\n\n    /* NEXT */\n\n    const next=\n        document.createElement(\n            \"button\"\n        );\n\n\n    next.type=\n        \"button\";\n\n\n    next.className=\n        \"ex-page\";\n\n\n    next.textContent=\n        CHAR.next;\n\n\n    next.setAttribute(\n        \"aria-label\",\n        \"Trang sau\"\n    );\n\n\n    next.disabled=\n        state.page\n        ===\n        total;\n\n\n    next.addEventListener(\n        \"click\",\n        function(){\n\n            if(\n                state.page\n                >=\n                total\n            ){\n\n                return;\n            }\n\n\n            goPage(\n                state.page+1\n            );\n        }\n    );\n\n\n    container.appendChild(\n        next\n    );\n}\n\n\n/* =========================================================\n   GO PAGE\n========================================================= */\n\nfunction goPage(page){\n\n    state.page=\n        page;\n\n\n    normalizePage();\n\n\n    renderGallery();\n\n\n    renderPages();\n\n\n    renderResultText();\n\n\n    const controls=\n        document.querySelector(\n            \"#ocdExhibitionPage .ex-controls\"\n        );\n\n\n    if(controls){\n\n        controls.scrollIntoView({\n            behavior:\n                \"smooth\",\n\n            block:\n                \"start\"\n        });\n    }\n}\n\n\n/* =========================================================\n   LIGHTBOX\n\n   KH\u00d4NG C\u00d3:\n   - \u0110i\u1ec3m\n   - Nh\u1eadn x\u00e9t GVCN\n========================================================= */\n\nfunction openLightbox(item){\n\n    if(!item){\n\n        return;\n    }\n\n\n    state.activeLightbox=\n        item;\n\n\n    state.lightboxToken++;\n\n\n    const token=\n        state.lightboxToken;\n\n\n    const box=\n        el(\n            \"exLightbox\"\n        );\n\n\n    const image=\n        el(\n            \"exLightboxImage\"\n        );\n\n\n    image.src=\n        item.largeImage\n        ||\n        item.image\n        ||\n        \"\";\n\n\n    image.alt=\n        item.assignment\n        ||\n        \"T\u00e1c ph\u1ea9m\";\n\n\n    /* NAME */\n\n    el(\"exLightboxName\")\n        .textContent=\n        item.name\n        ||\n        \"H\u1ecdc vi\u00ean\";\n\n\n    /* ASSIGNMENT */\n\n    const assignment=\n        el(\n            \"exLightboxAssignment\"\n        );\n\n\n    if(\n        item.assignment\n    ){\n\n        assignment.textContent=\n            item.assignment;\n\n\n        assignment.style.display=\n            \"block\";\n\n\n    }else{\n\n        assignment.textContent=\n            \"\";\n\n\n        assignment.style.display=\n            \"none\";\n    }\n\n\n    /* META */\n\n    const meta=[];\n\n\n    if(item.group){\n\n        meta.push(\n            \"T\u1ed5 \"\n            +\n            item.group\n        );\n    }\n\n\n    if(item.course){\n\n        meta.push(\n            \"Kh\u00f3a \"\n            +\n            item.course\n        );\n    }\n\n\n    el(\"exLightboxMeta\")\n        .textContent=\n        meta.join(\n            \" \"\n            +\n            CHAR.dot\n            +\n            \" \"\n        );\n\n\n    /* DATE */\n\n    const date=\n        el(\n            \"exLightboxDate\"\n        );\n\n\n    if(\n        item.timestamp\n    ){\n\n        date.textContent=\n            \"N\u1ed9p b\u00e0i: \"\n            +\n            item.timestamp;\n\n\n        date.style.display=\n            \"inline\";\n\n\n    }else{\n\n        date.textContent=\n            \"\";\n\n\n        date.style.display=\n            \"none\";\n    }\n\n\n    /* BEASTS */\n\n    const lightboxBeasts=\n        el(\n            \"exLightboxBeasts\"\n        );\n\n\n    lightboxBeasts.innerHTML=\"\";\n\n\n    lightboxBeasts.classList\n        .remove(\n            \"visible\"\n        );\n\n\n    hydrateLightboxBeasts(\n        item,\n        token\n    )\n    .catch(\n        function(error){\n\n            console.warn(\n                \"[OCD Exhibition Lightbox Beasts]\",\n                error\n            );\n        }\n    );\n\n\n    /* ORIGINAL */\n\n    const original=\n        el(\n            \"exOriginalLink\"\n        );\n\n\n    if(\n        item.originalUrl\n    ){\n\n        original.href=\n            item.originalUrl;\n\n\n        original.style.display=\n            \"inline-flex\";\n\n\n    }else{\n\n        original.removeAttribute(\n            \"href\"\n        );\n\n\n        original.style.display=\n            \"none\";\n    }\n\n\n    /* OPEN */\n\n    box.classList\n        .add(\n            \"visible\"\n        );\n\n\n    box.setAttribute(\n        \"aria-hidden\",\n        \"false\"\n    );\n\n\n    document.documentElement\n        .style\n        .overflow=\n        \"hidden\";\n}\n\n\n/* =========================================================\n   CLOSE LIGHTBOX\n========================================================= */\n\nfunction closeLightbox(){\n\n    state.lightboxToken++;\n\n\n    const box=\n        el(\n            \"exLightbox\"\n        );\n\n\n    box.classList\n        .remove(\n            \"visible\"\n        );\n\n\n    box.setAttribute(\n        \"aria-hidden\",\n        \"true\"\n    );\n\n\n    el(\"exLightboxImage\")\n        .removeAttribute(\n            \"src\"\n        );\n\n\n    const beasts=\n        el(\n            \"exLightboxBeasts\"\n        );\n\n\n    if(beasts){\n\n        beasts.innerHTML=\"\";\n\n\n        beasts.classList\n            .remove(\n                \"visible\"\n            );\n    }\n\n\n    document.documentElement\n        .style\n        .overflow=\n        \"\";\n\n\n    state.activeLightbox=\n        null;\n}\n\n\n/* =========================================================\n   RESET\n========================================================= */\n\nfunction resetFilters(){\n\n    el(\"exSearch\")\n        .value=\n        \"\";\n\n\n    el(\"exCourse\")\n        .value=\n        \"\";\n\n\n    el(\"exGroup\")\n        .value=\n        \"\";\n\n\n    el(\"exSort\")\n        .value=\n        \"newest\";\n\n\n    state.page=\n        1;\n\n\n    applyFilters(\n        false\n    );\n}\n\n\n/* =========================================================\n   SEARCH\n========================================================= */\n\nlet searchTimer=\n    null;\n\n\nfunction scheduleSearch(){\n\n    clearTimeout(\n        searchTimer\n    );\n\n\n    searchTimer=\n        setTimeout(\n            function(){\n\n                applyFilters(\n                    true\n                );\n\n            },\n            180\n        );\n}\n\n\n/* =========================================================\n   EVENTS\n========================================================= */\n\nfunction bindEvents(){\n\n    el(\"exSearch\")\n        .addEventListener(\n            \"input\",\n            scheduleSearch\n        );\n\n\n    el(\"exCourse\")\n        .addEventListener(\n            \"change\",\n            function(){\n\n                applyFilters(\n                    true\n                );\n            }\n        );\n\n\n    el(\"exGroup\")\n        .addEventListener(\n            \"change\",\n            function(){\n\n                applyFilters(\n                    true\n                );\n            }\n        );\n\n\n    el(\"exSort\")\n        .addEventListener(\n            \"change\",\n            function(){\n\n                applyFilters(\n                    true\n                );\n            }\n        );\n\n\n    el(\"exReset\")\n        .addEventListener(\n            \"click\",\n            resetFilters\n        );\n\n\n    el(\"exClose\")\n        .addEventListener(\n            \"click\",\n            closeLightbox\n        );\n\n\n    el(\"exLightbox\")\n        .addEventListener(\n            \"click\",\n            function(event){\n\n                if(\n                    event.target\n                    ===\n                    this\n                ){\n\n                    closeLightbox();\n                }\n            }\n        );\n\n\n    document.addEventListener(\n        \"keydown\",\n        function(event){\n\n            if(\n                event.key\n                ===\n                \"Escape\"\n\n                &&\n\n                el(\"exLightbox\")\n                    .classList\n                    .contains(\n                        \"visible\"\n                    )\n            ){\n\n                closeLightbox();\n            }\n        }\n    );\n}\n\n\n/* =========================================================\n   RESPONSIVE\n========================================================= */\n\nconst mobileMedia=\n    window.matchMedia(\n        \"(max-width:700px)\"\n    );\n\n\nfunction viewportChanged(){\n\n    state.page=\n        1;\n\n\n    renderGallery();\n\n\n    renderPages();\n\n\n    renderResultText();\n}\n\n\nif(\n    typeof mobileMedia\n        .addEventListener\n        ===\n        \"function\"\n){\n\n    mobileMedia.addEventListener(\n        \"change\",\n        viewportChanged\n    );\n\n\n}else if(\n    typeof mobileMedia\n        .addListener\n        ===\n        \"function\"\n){\n\n    mobileMedia.addListener(\n        viewportChanged\n    );\n}\n\n\n/* =========================================================\n   CORE PROFILE CHANGED\n========================================================= */\n\nwindow.addEventListener(\n    \"ocdRewardProfileChanged\",\n    function(event){\n\n        const detail=\n            event\n            &&\n            event.detail\n            ?\n            event.detail\n            :\n            {};\n\n\n        const code=\n            normalizeCode(\n                detail.code\n                ||\n                detail.studentCode\n                ||\n                \"\"\n            );\n\n\n        if(code){\n\n            state.accountMap\n                .delete(\n                    code\n                );\n\n\n            state.accountPromiseMap\n                .delete(\n                    code\n                );\n\n\n        }else{\n\n            state.accountMap\n                .clear();\n\n\n            state.accountPromiseMap\n                .clear();\n        }\n\n\n        renderGallery();\n\n\n        if(\n            state.activeLightbox\n\n            &&\n\n            (\n                !code\n\n                ||\n\n                normalizeCode(\n                    state.activeLightbox\n                        .code\n                )\n                ===\n                code\n            )\n        ){\n\n            const active=\n                state.activeLightbox;\n\n\n            state.lightboxToken++;\n\n\n            hydrateLightboxBeasts(\n                active,\n                state.lightboxToken\n            )\n            .catch(\n                function(error){\n\n                    console.warn(\n                        \"[OCD Exhibition Lightbox Refresh]\",\n                        error\n                    );\n                }\n            );\n        }\n    }\n);\n\n\n/* =========================================================\n   PUBLIC API\n========================================================= */\n\nwindow.OCDExhibition={\n\n    version:\n        CONFIG.version,\n\n\n    refresh:\n        async function(){\n\n            state.accountMap\n                .clear();\n\n\n            state.accountPromiseMap\n                .clear();\n\n\n            await loadData();\n\n\n            return state.exhibitionWorks\n                .slice();\n        },\n\n\n    getWorks:\n        function(){\n\n            return state.exhibitionWorks\n                .slice();\n        },\n\n\n    getFilteredWorks:\n        function(){\n\n            return state.filteredWorks\n                .slice();\n        },\n\n\n    clearProfileCache:\n        function(){\n\n            state.accountMap\n                .clear();\n\n\n            state.accountPromiseMap\n                .clear();\n\n\n            state.giftMap\n                .clear();\n\n\n            state.catalogReady=\n                false;\n\n\n            state.catalogPromise=\n                null;\n\n\n            renderGallery();\n\n\n            if(\n                state.activeLightbox\n            ){\n\n                const active=\n                    state.activeLightbox;\n\n\n                state.lightboxToken++;\n\n\n                hydrateLightboxBeasts(\n                    active,\n                    state.lightboxToken\n                )\n                .catch(\n                    function(error){\n\n                        console.warn(\n                            \"[OCD Exhibition Lightbox Cache]\",\n                            error\n                        );\n                    }\n                );\n            }\n        },\n\n\n    getState:\n        function(){\n\n            return{\n\n                version:\n                    CONFIG.version,\n\n                qualificationMode:\n                    \"teacher-comment-keyword\",\n\n                exhibitionKeyword:\n                    CONFIG.exhibitionKeyword,\n\n                /*\n                   Keyword ch\u1ec9 d\u00f9ng n\u1ed9i b\u1ed9.\n                   Kh\u00f4ng render nh\u1eadn x\u00e9t.\n                */\n\n                scoreVisible:\n                    false,\n\n                commentVisible:\n                    false,\n\n                scoreSortingEnabled:\n                    false,\n\n                totalSourceWorks:\n                    state.allWorks.length,\n\n                exhibitionWorks:\n                    state.exhibitionWorks.length,\n\n                filteredWorks:\n                    state.filteredWorks.length,\n\n                deletedWorks:\n                    state.deletedIds.size,\n\n                page:\n                    state.page,\n\n                pages:\n                    pageCount(),\n\n                pageSize:\n                    pageSize(),\n\n                rewardCoreAvailable:\n                    coreReady(),\n\n                cachedAccounts:\n                    state.accountMap.size,\n\n                catalogReady:\n                    state.catalogReady,\n\n                catalogItems:\n                    state.giftMap.size,\n\n                excludedNotes:\n                    CONFIG.excludedNotes\n                        .slice(),\n\n                avatarEnabled:\n                    true,\n\n                spiritBeastEnabled:\n                    true,\n\n                spiritBeastPosition:\n                    \"footer-and-lightbox\",\n\n                mobileLightboxCompact:\n                    true\n\n            };\n        }\n\n};\n\n\n/* =========================================================\n   START\n========================================================= */\n\nfunction start(){\n\n    if(\n        state.started\n    ){\n\n        return;\n    }\n\n\n    state.started=\n        true;\n\n\n    el(\"exClose\")\n        .textContent=\n        CHAR.close;\n\n\n    bindEvents();\n\n\n    loadData()\n        .catch(\n            function(error){\n\n                console.error(\n                    \"[OCD Exhibition Start]\",\n                    error\n                );\n            }\n        );\n}\n\n\n/* =========================================================\n   DOM READY\n========================================================= */\n\nif(\n    document.readyState\n    ===\n    \"loading\"\n){\n\n    document.addEventListener(\n        \"DOMContentLoaded\",\n        start,\n        {\n            once:true\n        }\n    );\n\n\n}else{\n\n    start();\n}\n\n\n})();\n</script>\n\n</div>");})();
